/*
 * HowToStudyKorean Unit 1 usage notes — the context layer under each word's ＋
 * on howtostudykorean-unit-1.html, written in the style of topik-i-notes.js.
 *
 * Keyed by the page's word id (l<lesson>-<pos>-<romanization>, or the word's
 * own id where two words share a spelling), so 배 the stomach and 배 the boat,
 * or 걷다 to walk and 걷다 to tuck, each get their own note.
 *
 * Each note carries:
 *   note    - how the word is actually used, and what learners mix it up with
 *   example - { ko, en, form }, where form says what happened to the words in
 *             the sentence, e.g. "크다 → 커요 (ㅡ drops before -어요)"
 *
 * These are written for this site, not taken from HowToStudyKorean; the
 * lesson's own notes, usages and examples stay in the page's UNIT data.
 *
 * Browser: <script src="./shared-vocab/htsk-unit-1-notes.js"></script> -> window.HtskUnit1Notes
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.HtskUnit1Notes = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const NOTES = {
    // ============================================================== lesson 1
    "l1-noun-han-guk": { note: "The everyday name for South Korea; 대한민국 is the formal one. Put 사람 or -어 after it for the people and the language: 한국 사람, 한국어.", example: { ko: "저는 한국에 살아요.", en: "I live in Korea.", form: "한국 + 에 (location particle); 살다 → 살아요 (present, polite casual)" } },
    "l1-noun-do-si": { note: "A city in general. A named city usually drops it (서울, not 서울 도시); 도시 shows up in compounds like 대도시 (big city) and 도시 생활 (city life).", example: { ko: "서울은 큰 도시예요.", en: "Seoul is a big city.", form: "크다 → 큰 (adjective modifying a noun); 도시 + 예요 (이다 after a vowel)" } },
    "l1-noun-i-reum": { note: "Someone's name, or the name of a thing. Asking an older person, use the honorific 성함 instead: 성함이 어떻게 되세요?", example: { ko: "제 이름은 민수예요.", en: "My name is Minsu.", form: "제 = 저의 (my, humble); 이름 + 은 (topic particle after a batchim)" } },
    "l1-noun-jeo": { note: "The humble 'I', for anyone older or anyone you are being polite to. With 이/가 it becomes 제가, and 'my' is 제 (short for 저의).", example: { ko: "저는 학생이에요.", en: "I am a student.", form: "저 + 는 (topic particle); 학생 + 이에요 (이다 after a batchim)" } },
    "l1-noun-na": { note: "The plain 'I', only with close friends, younger people, or in writing to yourself. With 이/가 it becomes 내가, and 'my' is 내.", example: { ko: "나는 커피를 좋아해.", en: "I like coffee.", form: "좋아하다 → 좋아해 (present, casual speech)" } },
    "l1-noun-nam-ja": { note: "Man or male. It is also used for 'boyfriend' in 남자 친구 (often shortened to 남친).", example: { ko: "그 남자는 의사예요.", en: "That man is a doctor.", form: "그 (that) + 남자 + 는 (topic particle); 의사 + 예요" } },
    "l1-noun-yeo-ja": { note: "Woman or female. 여자 친구 (여친) is 'girlfriend'.", example: { ko: "이 여자는 제 친구예요.", en: "This woman is my friend.", form: "이 (this) + 여자 + 는; 친구 + 예요 (이다 after a vowel)" } },
    "l1-noun-i": { note: "'This', for something near you. It cannot stand alone: it always sits in front of a noun (이 책, 이 사람), or joins 것 to make 이것.", example: { ko: "이 책은 비싸요.", en: "This book is expensive.", form: "이 + 책 (noun directly after); 비싸다 → 비싸요 (present, polite casual)" } },
    "l1-noun-geu": { note: "'That', for something near the listener or already mentioned. Like 이, it needs a noun after it. Alone, 그 can also mean 'he'.", example: { ko: "그 사람은 누구예요?", en: "Who is that person?", form: "그 + 사람 (noun directly after); 누구 + 예요 (이다)" } },
    "l1-noun-jeo-far": { note: "'That over there', for something far from both of you. It needs a noun after it: 저 건물, 저 사람.", example: { ko: "저 건물은 학교예요.", en: "That building over there is a school.", form: "저 + 건물 + 은 (topic particle after a batchim)" } },
    "l1-noun-geos": { note: "'Thing', a noun that needs something in front of it: 이것, 제 것 (mine), 먹을 것 (something to eat). In speech, 것 is often shortened to 거.", example: { ko: "이거는 제 거예요.", en: "This is mine.", form: "이것 → 이거, 것 → 거 (spoken short forms); 제 + 거 + 예요" } },
    "l1-noun-i-geos": { note: "'This thing', near the speaker. In speech it is usually 이거, and with particles 이게 (이것이) and 이걸 (이것을).", example: { ko: "이것은 펜이에요.", en: "This is a pen.", form: "이것 + 은 (topic particle); 펜 + 이에요 (이다 after a batchim)" } },
    "l1-noun-geu-geos": { note: "'That thing', near the listener or just mentioned. Spoken: 그거, 그게, 그걸.", example: { ko: "그게 뭐예요?", en: "What is that?", form: "그것 + 이 → 그게 (spoken contraction); 뭐 + 예요" } },
    "l1-noun-jeo-geos": { note: "'That thing over there', far from both people. Spoken: 저거, 저게, 저걸.", example: { ko: "저것은 제 차예요.", en: "That over there is my car.", form: "저것 + 은 (topic particle); 차 + 예요 (이다 after a vowel)" } },
    "l1-noun-eui-ja": { note: "A chair or seat. To sit on it is 의자에 앉다, with 에 for the place.", example: { ko: "의자에 앉으세요.", en: "Please have a seat.", form: "의자 + 에 (location); 앉다 → 앉으세요 (polite request, -(으)세요)" } },
    "l1-noun-tak-ja": { note: "A table, especially a low or side table. A table for eating or a desk is often 식탁 (dining table) or 책상 (desk).", example: { ko: "탁자 위에 책이 있어요.", en: "There is a book on the table.", form: "탁자 + 위 + 에 (on top of); 책 + 이 (subject particle); 있다 → 있어요" } },
    "l1-noun-seon-saeng-nim": { note: "Teacher, with the honorific -님 built in. It is also a polite way to address doctors and other professionals. Never call yourself 선생님; say 교사 for your job.", example: { ko: "선생님, 질문이 있어요.", en: "Teacher, I have a question.", form: "선생님 used as a form of address; 질문 + 이 (subject particle); 있다 → 있어요" } },
    "l1-noun-chim-dae": { note: "A bed (Western style). A traditional floor mattress is 요 or 이불. 'Go to bed' is usually 자러 가다, not a phrase with 침대.", example: { ko: "제 방에 침대가 있어요.", en: "There is a bed in my room.", form: "방 + 에 (location); 침대 + 가 (subject particle after a vowel)" } },
    "l1-noun-jip": { note: "A house, and also 'home'. 집에 가다 is 'to go home'. The honorific is 댁: 선생님 댁.", example: { ko: "지금 집에 가요.", en: "I'm going home now.", form: "집 + 에 (destination); 가다 → 가요 (present, polite casual)" } },
    "l1-noun-cha": { note: "A car or vehicle. A different 차 means tea (Lesson 6), so context decides: 차를 마시다 is tea, 차를 타다 is a car.", example: { ko: "아버지의 차는 커요.", en: "My father's car is big.", form: "아버지 + 의 (possessive); 크다 → 커요 (ㅡ drops before -어요)" } },
    "l1-noun-sa-ram": { note: "A person; with a country it means a national: 한국 사람 (a Korean). 'People' is still 사람, or 사람들 when the plural matters.", example: { ko: "저 사람은 미국 사람이에요.", en: "That person is American.", form: "미국 + 사람 (nationality); 사람 + 이에요 (이다 after a batchim)" } },
    "l1-noun-chaek": { note: "A book. Reading one is 책을 읽다; a bookstore is 서점 or 책방.", example: { ko: "저는 책을 읽어요.", en: "I read a book.", form: "책 + 을 (object particle after a batchim); 읽다 → 읽어요" } },
    "l1-noun-keom-pyu-teo": { note: "A computer, borrowed from English. A laptop is 노트북 (from 'notebook'), not 랩탑.", example: { ko: "컴퓨터가 너무 느려요.", en: "The computer is too slow.", form: "컴퓨터 + 가 (subject particle); 느리다 → 느려요 (ㅣ + 어 → ㅕ)" } },
    "l1-noun-na-mu": { note: "Both a tree and wood as a material: 나무 의자 is a wooden chair.", example: { ko: "공원에 나무가 많아요.", en: "There are a lot of trees in the park.", form: "공원 + 에 (location); 많다 → 많아요 (present, polite casual)" } },
    "l1-noun-so-pa": { note: "A sofa or couch, from English.", example: { ko: "소파에 고양이가 있어요.", en: "There is a cat on the sofa.", form: "소파 + 에 (location); 고양이 + 가 (subject particle)" } },
    "l1-noun-jung-guk": { note: "China. 중국 사람 is a Chinese person, 중국어 the Chinese language, and 중국 음식 Chinese food.", example: { ko: "중국은 아주 큰 나라예요.", en: "China is a very big country.", form: "아주 (very) + 큰 (크다 as a modifier) + 나라 + 예요" } },
    "l1-noun-il-bon": { note: "Japan. 일본 사람 is a Japanese person, 일본어 the Japanese language.", example: { ko: "제 친구는 일본에서 왔어요.", en: "My friend came from Japan.", form: "일본 + 에서 (from); 오다 → 왔어요 (past, 오 + 았 → 왔)" } },
    "l1-noun-mun": { note: "A door or gate. 문을 열다 is to open it and 문을 닫다 to close it; 창문 (Lesson 2) is a window.", example: { ko: "문을 닫아요.", en: "I close the door.", form: "문 + 을 (object particle); 닫다 → 닫아요 (present, polite casual)" } },
    "l1-noun-eui-sa": { note: "A doctor, as a job title. Speaking to a doctor, Koreans say 의사 선생님 or just 선생님.", example: { ko: "제 어머니는 의사예요.", en: "My mother is a doctor.", form: "의사 + 예요 (이다 after a vowel)" } },
    "l1-noun-hak-saeng": { note: "A student at any level. 대학생 is a university student, 고등학생 a high-school student.", example: { ko: "저는 대학생이에요.", en: "I am a university student.", form: "대학 + 학생 → 대학생; 이에요 (이다 after a batchim)" } },
    "l1-adverb-i-da": { note: "'To be' in the sense 'A is B', joined straight onto the noun: 학생이다. In speech it is 이에요 after a batchim, 예요 after a vowel. For 'to be at a place', use 있다 instead.", example: { ko: "이것은 사과예요.", en: "This is an apple.", form: "사과 + 이다 → 사과예요 (예요 after a vowel)" } },
    "l1-adverb-ne": { note: "'Yes', and also the polite 'I see / okay' that keeps a conversation going. 예 is a more formal version. It agrees with what was said, so answering a negative question it can mean 'no'.", example: { ko: "네, 맞아요.", en: "Yes, that's right.", form: "맞다 → 맞아요 (present, polite casual)" } },
    "l1-adverb-a-ni": { note: "'No' in casual speech. The polite answer is 아니요 (or 아뇨). Don't confuse it with 아니다, 'to not be', as in 학생이 아니에요.", example: { ko: "아니요, 저는 학생이 아니에요.", en: "No, I am not a student.", form: "아니요 (polite no); 학생 + 이 아니다 → 이 아니에요 (is not)" } },

    // ============================================================== lesson 2
    "l2-noun-na-ra": { note: "A country or nation. 'Which country are you from?' is 어느 나라 사람이에요?", example: { ko: "어느 나라 사람이에요?", en: "What country are you from?", form: "어느 (which) + 나라 + 사람 + 이에요" } },
    "l2-noun-ga-bang": { note: "Any bag: a backpack, a handbag or a briefcase.", example: { ko: "가방 안에 책이 있어요.", en: "There is a book in the bag.", form: "가방 + 안 + 에 (inside); 있다 → 있어요" } },
    "l2-noun-chang-mun": { note: "A window: 창 (window) + 문 (door). Opening it is 창문을 열다.", example: { ko: "창문을 열어요.", en: "I open the window.", form: "창문 + 을; 열다 → 열어요 (present, polite casual)" } },
    "l2-noun-jap-ji": { note: "A magazine. 'Read a magazine' is 잡지를 읽다; 'look at a magazine' is 잡지를 보다.", example: { ko: "책상 위에 잡지가 있어요.", en: "There's a magazine on the desk.", form: "책상 + 위 + 에 (on top of); 잡지 + 가" } },
    "l2-noun-bang": { note: "A room, especially a bedroom. It also ends many place words: 노래방 (karaoke room), PC방 (internet café).", example: { ko: "제 방은 작아요.", en: "My room is small.", form: "방 + 은 (topic particle); 작다 → 작아요" } },
    "l2-noun-naeng-jang-go": { note: "A refrigerator. The freezer is 냉동고 or 냉동실.", example: { ko: "냉장고에 우유가 있어요.", en: "There's milk in the fridge.", form: "냉장고 + 에 (location); 우유 + 가 (subject)" } },
    "l2-noun-gae": { note: "A dog. Careful: the same spelling is also a counter for things (사과 세 개), and 개- in front of a word makes slang stronger.", example: { ko: "개가 공원에 있어요.", en: "The dog is in the park.", form: "개 + 가 (subject); 공원 + 에 (location)" } },
    "l2-noun-gang-a-ji": { note: "A puppy, and also the everyday affectionate word for a pet dog of any age.", example: { ko: "강아지가 아주 귀여워요.", en: "The puppy is very cute.", form: "귀엽다 → 귀여워요 (ㅂ irregular: ㅂ → 우)" } },
    "l2-noun-go-yang-i": { note: "A cat. A kitten is 새끼 고양이.", example: { ko: "저는 고양이를 좋아해요.", en: "I like cats.", form: "고양이 + 를 (object particle after a vowel); 좋아하다 → 좋아해요" } },
    "l2-noun-jui": { note: "A rat or a mouse; Korean doesn't separate the two. A computer mouse is 마우스.", example: { ko: "부엌에 쥐가 있어요!", en: "There's a mouse in the kitchen!", form: "부엌 + 에 (location); 쥐 + 가 (subject)" } },
    "l2-noun-pen": { note: "A pen, from English. A ballpoint is 볼펜, and a pencil is 연필.", example: { ko: "펜이 있어요?", en: "Do you have a pen?", form: "펜 + 이 (subject); 있다 → 있어요? (question by rising tone)" } },
    "l2-noun-jeon-hoa-gi": { note: "A telephone as a device. A mobile phone is 핸드폰 or 휴대폰, and 'to call' is 전화하다.", example: { ko: "전화기가 탁자 위에 있어요.", en: "The phone is on the table.", form: "전화기 + 가; 탁자 + 위 + 에 (on top of)" } },
    "l2-noun-keo-pi": { note: "Coffee, from English. 'Drink coffee' is 커피를 마시다; an iced Americano is 아이스 아메리카노, or 아아 in slang.", example: { ko: "아침에 커피를 마셔요.", en: "I drink coffee in the morning.", form: "아침 + 에 (time); 마시다 → 마셔요 (ㅣ + 어 → ㅕ)" } },
    "l2-noun-sik-dang": { note: "A restaurant, especially an ordinary one for meals; 레스토랑 sounds fancier. It is also a cafeteria: 학생 식당.", example: { ko: "학교 앞에 식당이 있어요.", en: "There is a restaurant in front of the school.", form: "학교 + 앞 + 에 (in front of); 식당 + 이 (subject)" } },
    "l2-noun-geon-mul": { note: "A building, any structure you can go into.", example: { ko: "저 건물은 아주 높아요.", en: "That building is very tall.", form: "저 (that over there) + 건물 + 은; 높다 → 높아요" } },
    "l2-noun-tel-re-bi-jeon": { note: "A television; in speech usually shortened to 티비 or TV. Watching it is 텔레비전을 보다.", example: { ko: "저녁에 텔레비전을 봐요.", en: "I watch TV in the evening.", form: "저녁 + 에 (time); 보다 → 봐요 (오 + 아 → 와)" } },
    "l2-noun-mi-guk": { note: "The USA. 미국 사람 is an American; 'English' is still 영어, not 미국어.", example: { ko: "제 친구는 미국 사람이에요.", en: "My friend is American.", form: "미국 + 사람 (nationality); 이에요 (이다)" } },
    "l2-noun-kae-na-da": { note: "Canada, from English. 캐나다 사람 is a Canadian.", example: { ko: "캐나다는 겨울에 아주 추워요.", en: "Canada is very cold in winter.", form: "겨울 + 에 (time); 춥다 → 추워요 (ㅂ irregular)" } },
    "l2-noun-ho-tel": { note: "A hotel, from English. 'Stay at a hotel' is 호텔에서 묵다 or 호텔에서 자다.", example: { ko: "호텔은 공항 옆에 있어요.", en: "The hotel is next to the airport.", form: "공항 + 옆 + 에 (next to); 있다 → 있어요" } },
    "l2-noun-hak-gyo": { note: "A school, especially primary to high school; a university is 대학교. 'Go to school' is 학교에 가다.", example: { ko: "저는 매일 학교에 가요.", en: "I go to school every day.", form: "학교 + 에 (destination); 가다 → 가요" } },
    "l2-noun-eun-haeng": { note: "A bank (for money). A riverbank is 강둑, a completely different word.", example: { ko: "은행은 어디에 있어요?", en: "Where is the bank?", form: "어디 + 에 (where, location); 있다 → 있어요?" } },
    "l2-adverb-an": { note: "The inside of something, used after a noun with 에: 가방 안에 (in the bag). Not to be confused with the negating 안 in front of a verb (안 가요, 'I'm not going').", example: { ko: "방 안에 고양이가 있어요.", en: "There's a cat in the room.", form: "방 + 안 + 에 (inside); 고양이 + 가 (subject)" } },
    "l2-adverb-ui": { note: "The top of something or above it, after a noun with 에: 책상 위에 (on the desk). Its opposite is 밑 or 아래.", example: { ko: "책상 위에 컴퓨터가 있어요.", en: "There's a computer on the desk.", form: "책상 + 위 + 에 (on top of); 있다 → 있어요" } },
    "l2-adverb-mit": { note: "Under or beneath something, after a noun with 에: 침대 밑에. 아래 means much the same; 밑 suggests directly underneath and touching.", example: { ko: "침대 밑에 가방이 있어요.", en: "There's a bag under the bed.", form: "침대 + 밑 + 에 (under); 가방 + 이 (subject)" } },
    "l2-adverb-yeop": { note: "The side of something, so 'next to': 학교 옆에 (next to the school).", example: { ko: "은행 옆에 식당이 있어요.", en: "There's a restaurant next to the bank.", form: "은행 + 옆 + 에 (next to); 식당 + 이" } },
    "l2-adverb-dui": { note: "Behind, and also 'after' in time (식사 뒤에, after the meal). Its opposite is 앞.", example: { ko: "집 뒤에 공원이 있어요.", en: "There's a park behind the house.", form: "집 + 뒤 + 에 (behind); 공원 + 이" } },
    "l2-adverb-ap": { note: "The front, so 'in front of': 학교 앞에. In time it can mean 'ahead' or 'before'.", example: { ko: "역 앞에서 만나요.", en: "Let's meet in front of the station.", form: "역 + 앞 + 에서 (place of an action); 만나다 → 만나요 (suggestion)" } },
    "l2-adverb-yeo-gi": { note: "'Here', near the speaker. It goes with 거기 (there, near you) and 저기 (over there). 여기요! calls a waiter.", example: { ko: "여기에 앉으세요.", en: "Please sit here.", form: "여기 + 에 (location); 앉다 → 앉으세요 (polite request)" } },
    "l2-verb-iss-da": { note: "'To be (at a place)': the thing is the subject with 이/가 and the place takes 에. Its opposite is 없다. The honorific is 계시다.", example: { ko: "고양이가 의자 밑에 있어요.", en: "The cat is under the chair.", form: "있다 → 있어요 (present, polite casual); 밑 + 에 (location)" } },
    "l2-adjective-iss-da": { note: "'To have': the owner is usually the topic (저는) and the thing takes 이/가, not 을/를. 'Not to have' is 없다.", example: { ko: "저는 차가 있어요.", en: "I have a car.", form: "차 + 가 (the thing had is the subject); 있다 → 있어요" } },

    // ============================================================== lesson 3
    "l3-noun-eum-sik": { note: "Food in general, or a dish. 한국 음식 is Korean food; for a meal, Koreans more often say 밥 (Lesson 5).", example: { ko: "한국 음식은 맛있어요.", en: "Korean food is delicious.", form: "음식 + 은 (topic particle); 맛있다 → 맛있어요" } },
    "l3-noun-ke-i-keu": { note: "Cake, from English. A birthday cake is 생일 케이크.", example: { ko: "제가 케이크를 만들었어요.", en: "I made a cake.", form: "제가 (I, with 가); 만들다 → 만들었어요 (past)" } },
    "l3-noun-gong-hang": { note: "An airport. 인천 공항 is Seoul's main international one.", example: { ko: "공항에 버스로 가요.", en: "I go to the airport by bus.", form: "공항 + 에 (destination); 버스 + 로 (by means of)" } },
    "l3-noun-byeong-ueon": { note: "A hospital, and also a doctor's clinic. 병원에 가다 is 'to go to the doctor'.", example: { ko: "오늘 병원에 가요.", en: "I'm going to the hospital today.", form: "병원 + 에 (destination); 가다 → 가요" } },
    "l3-noun-gong-ueon": { note: "A park. Many apartment complexes have a small one; 놀이공원 is an amusement park.", example: { ko: "공원에서 걸어요.", en: "I walk in the park.", form: "공원 + 에서 (place of an action); 걷다 → 걸어요 (ㄷ irregular)" } },
    "l3-noun-han-guk-eo": { note: "The Korean language: 한국 + -어 (language). 한글 is the alphabet, not the language, and 국어 is what Koreans call their own language class.", example: { ko: "저는 한국어를 배워요.", en: "I learn Korean.", form: "한국어 + 를 (object); 배우다 → 배워요 (우 + 어 → 워)" } },
    "l3-noun-meo-ri": { note: "The head, and also the hair on it. 머리가 아프다 is 'to have a headache'; 머리가 좋다 is 'to be smart'.", example: { ko: "머리가 아파요.", en: "I have a headache.", form: "머리 + 가 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "l3-noun-da-ri": { note: "A leg. The same spelling also means a bridge, and context tells them apart.", example: { ko: "다리가 길어요.", en: "(Their) legs are long.", form: "다리 + 가 (subject); 길다 → 길어요" } },
    "l3-noun-son-ga-rak": { note: "A finger: 손 (hand) + 가락 (a long thin piece). A toe is 발가락, and chopsticks are 젓가락.", example: { ko: "손가락이 다섯 개 있어요.", en: "There are five fingers.", form: "손가락 + 이 (subject); 다섯 개 (five, native number + counter)" } },
    "l3-noun-gui": { note: "An ear. 귀엽다 (cute) is unrelated. 'Listen carefully' is 귀를 기울이다, to tilt your ear.", example: { ko: "토끼는 귀가 길어요.", en: "Rabbits have long ears.", form: "토끼는 (topic) + 귀가 (subject): 'as for rabbits, the ears are long'" } },
    "l3-noun-pal": { note: "An arm. The same spelling is also the Sino-Korean number eight.", example: { ko: "팔이 아파요.", en: "My arm hurts.", form: "팔 + 이 (subject); 아프다 → 아파요" } },
    "l3-noun-nun": { note: "An eye. The same spelling means snow: 눈이 와요 is 'it's snowing', 눈이 커요 is '(their) eyes are big'.", example: { ko: "그 아이는 눈이 커요.", en: "That child has big eyes.", form: "아이는 (topic) + 눈이 (subject); 크다 → 커요" } },
    "l3-noun-ip": { note: "The mouth (and loosely the lips; the lips themselves are 입술). 입을 열다 is 'to start talking'.", example: { ko: "입을 크게 벌리세요.", en: "Open your mouth wide.", form: "크다 → 크게 (adverb, -게); 벌리다 → 벌리세요 (polite request)" } },
    "l3-noun-bae": { note: "The stomach or belly. The same spelling means a boat and a pear. 배가 고프다 is 'to be hungry', 배가 아프다 'to have a stomachache'.", example: { ko: "배가 아파요.", en: "I have a stomachache.", form: "배 + 가 (subject); 아프다 → 아파요" } },
    "l3-noun-beo-seu": { note: "A bus, from English. 'Take a bus' is 버스를 타다, and 'by bus' is 버스로.", example: { ko: "버스를 타요.", en: "I take the bus.", form: "버스 + 를 (object); 타다 → 타요 (vowels merge)" } },
    "l3-noun-bae-boat": { note: "A boat or ship. It shares its spelling with 배 (stomach) and 배 (pear). 'Go by boat' is 배로 가다; 'be seasick' is 뱃멀미를 하다.", example: { ko: "제주도에 배로 가요.", en: "I go to Jeju Island by boat.", form: "배 + 로 (by means of); 가다 → 가요" } },
    "l3-noun-u-ri": { note: "'We' or 'us', and very often 'my' where English uses 'my': 우리 엄마, 우리 집. The humble form is 저희.", example: { ko: "우리 집은 학교 옆에 있어요.", en: "My (our) house is next to the school.", form: "우리 + 집 (우리 for 'my' family/home); 옆 + 에 (next to)" } },
    "l3-verb-meok-da": { note: "To eat, and also to take medicine (약을 먹다) or to have a drink loosely. The honorific is 드시다 or 잡수시다.", example: { ko: "저는 아침을 먹어요.", en: "I eat breakfast.", form: "아침 + 을 (object); 먹다 → 먹어요 (present, polite casual)" } },
    "l3-verb-ga-da": { note: "To go, with the place marked by 에: 학교에 가다. With another verb it means 'go to do': 먹으러 가다.", example: { ko: "내일 공항에 가요.", en: "I'm going to the airport tomorrow.", form: "공항 + 에 (destination); 가다 → 가요 (가 + 아 → 가)" } },
    "l3-verb-man-na-da": { note: "To meet someone. The person takes 을/를 (친구를 만나다), or 와/과 for 'meet with'.", example: { ko: "주말에 친구를 만나요.", en: "I meet my friend on the weekend.", form: "친구 + 를 (object); 만나다 → 만나요" } },
    "l3-verb-dat-da": { note: "To close or shut something (a door, a window, a shop). Its opposite is 열다.", example: { ko: "창문을 닫으세요.", en: "Please close the window.", form: "닫다 → 닫으세요 (polite request; -으세요 after a batchim)" } },
    "l3-verb-yeol-da": { note: "To open something. The stem drops its ㄹ before ㄴ, ㅂ and ㅅ: 여세요, 엽니다.", example: { ko: "문을 열어요.", en: "I open the door.", form: "문 + 을 (object); 열다 → 열어요" } },
    "l3-verb-ueon-ha-da": { note: "To want a thing, with 을/를: 무엇을 원해요? It sounds formal; everyday speech says 'I want to do' with -고 싶다 instead.", example: { ko: "무엇을 원해요?", en: "What do you want?", form: "무엇 + 을 (object); 원하다 → 원해요 (하 + 여 → 해)" } },
    "l3-verb-man-deul-da": { note: "To make or create. It is an ㄹ stem: 만듭니다, 만드세요.", example: { ko: "어머니가 음식을 만들어요.", en: "My mother makes food.", form: "음식 + 을 (object); 만들다 → 만들어요" } },
    "l3-verb-ha-da": { note: "To do. It turns many nouns into verbs (공부하다, 운동하다), and its conjugations are irregular: 해요, 했어요, 합니다.", example: { ko: "지금 뭐 해요?", en: "What are you doing now?", form: "하다 → 해요 (하 + 여 → 해; present, polite casual)" } },
    "l3-verb-mal-ha-da": { note: "To speak or say. 'Speak Korean' is 한국어로 말하다 or 한국어를 하다. The honorific is 말씀하시다.", example: { ko: "천천히 말해 주세요.", en: "Please speak slowly.", form: "말하다 → 말해 + 주세요 (please do it for me)" } },
    "l3-verb-i-hae-ha-da": { note: "To understand something, with 을/를. 'I don't understand' is 이해가 안 돼요 or 이해 못 해요.", example: { ko: "저는 그 말을 이해해요.", en: "I understand what (they) said.", form: "말 + 을 (object); 이해하다 → 이해해요" } },
    "l3-verb-joh-a-ha-da": { note: "To like something, with 을/를: 커피를 좋아해요. Compare 좋다 (to be good), where the thing is the subject: 커피가 좋아요.", example: { ko: "저는 고양이를 좋아해요.", en: "I like cats.", form: "고양이 + 를 (object); 좋아하다 → 좋아해요" } },
    "l3-adjective-keu-da": { note: "To be big; also tall (키가 크다) and loud (소리가 크다). The ㅡ drops before -어: 커요. As a modifier: 큰 집.", example: { ko: "이 가방은 너무 커요.", en: "This bag is too big.", form: "크다 → 커요 (ㅡ drops before -어요)" } },
    "l3-adjective-jak-da": { note: "To be small; also short in height (키가 작다). Its opposite is 크다. As a modifier: 작은 방.", example: { ko: "제 방은 작아요.", en: "My room is small.", form: "작다 → 작아요 (present, polite casual)" } },
    "l3-adjective-sae-rop-da": { note: "To be new or fresh, often in an abstract sense (a new idea, a new feeling). For a new object, Koreans usually say 새 in front of the noun: 새 차.", example: { ko: "새로운 친구를 만났어요.", en: "I met a new friend.", form: "새롭다 → 새로운 (ㅂ irregular modifier); 만나다 → 만났어요" } },
    "l3-adjective-nalk-da": { note: "To be old and worn out, for things only: 낡은 신발. For a person, use 늙다; for something simply having been around long, 오래되다.", example: { ko: "이 집은 아주 낡았어요.", en: "This house is very old and worn.", form: "낡다 → 낡았어요 (past form describes its state)" } },
    "l3-adjective-bi-ssa-da": { note: "To be expensive. Its opposite is 싸다. 'How much is it?' is 얼마예요?", example: { ko: "서울은 집이 비싸요.", en: "Houses are expensive in Seoul.", form: "서울은 (topic) + 집이 (subject); 비싸다 → 비싸요" } },
    "l3-adjective-ssa-da": { note: "To be cheap. Careful: 싸다 also means 'to wrap/pack' (가방을 싸다) and, in slang, 'to poop'.", example: { ko: "이 시장은 과일이 싸요.", en: "Fruit is cheap at this market.", form: "과일 + 이 (subject); 싸다 → 싸요" } },
    "l3-adjective-a-reum-dap-da": { note: "To be beautiful, a strong, slightly literary word for scenery, music or people. Everyday speech uses 예쁘다. ㅂ irregular: 아름다워요.", example: { ko: "가을 산이 아름다워요.", en: "The autumn mountains are beautiful.", form: "아름답다 → 아름다워요 (ㅂ irregular: ㅂ → 우)" } },
    "l3-adjective-ddung-ddung-ha-da": { note: "To be fat or chubby. It is blunt about people; it's gentler to use it about animals or yourself.", example: { ko: "우리 고양이는 좀 뚱뚱해요.", en: "Our cat is a bit chubby.", form: "좀 (a bit); 뚱뚱하다 → 뚱뚱해요" } },
    "l3-adjective-gil-da": { note: "To be long, in length or time. It is an ㄹ stem: 긴 머리 (long hair).", example: { ko: "그 영화는 너무 길어요.", en: "That movie is too long.", form: "길다 → 길어요 (present, polite casual)" } },
    "l3-adjective-joh-da": { note: "To be good or nice. 'I like X' often uses it: X가 좋아요. The ㅎ is silent before a vowel: 좋아요 sounds like 조아요.", example: { ko: "오늘 날씨가 좋아요.", en: "The weather is nice today.", form: "날씨 + 가 (subject); 좋다 → 좋아요" } },
    "l3-adverb-a-ju": { note: "'Very', placed before an adjective or adverb. It is neutral and common in both speech and writing.", example: { ko: "이 케이크는 아주 맛있어요.", en: "This cake is very delicious.", form: "아주 + 맛있어요 (adverb before the adjective)" } },
    "l3-adverb-mae-u": { note: "'Very', more formal and written than 아주. In speech, 정말 or 진짜 are far more common.", example: { ko: "오늘은 매우 추워요.", en: "It's very cold today.", form: "매우 + 추워요 (춥다, ㅂ irregular)" } },
    "l3-adverb-neo-mu": { note: "Strictly 'too (much)', but in everyday speech it just means 'really, so': 너무 좋아요 is 'I love it'.", example: { ko: "이 영화 너무 재미있어요!", en: "This movie is so fun!", form: "너무 + 재미있어요 (너무 as 'really')" } },

    // ============================================================== lesson 4
    "l4-noun-gil": { note: "A road or path, and also the way to somewhere: 길을 잃다 is 'to get lost'.", example: { ko: "길을 잃었어요.", en: "I got lost.", form: "길 + 을 (object); 잃다 → 잃었어요 (past)" } },
    "l4-noun-geo-ri": { note: "A street, especially a busy one with shops (명동 거리). The same spelling means 'distance' and 'material/stuff'.", example: { ko: "이 거리에는 카페가 많아요.", en: "There are many cafés on this street.", form: "거리 + 에 + 는 (location + topic); 많다 → 많아요" } },
    "l4-noun-son": { note: "A hand. 손을 씻다 is 'to wash your hands'; 손님 (guest) is a different word.", example: { ko: "밥 먹기 전에 손을 씻어요.", en: "I wash my hands before eating.", form: "먹다 + -기 전에 (before doing); 씻다 → 씻어요" } },
    "l4-noun-yeong-eo": { note: "The English language. 영국 is England/the UK; 영어 is used for English whoever speaks it.", example: { ko: "저는 영어를 가르쳐요.", en: "I teach English.", form: "영어 + 를 (object); 가르치다 → 가르쳐요" } },
    "l4-noun-taek-si": { note: "A taxi. 'Take a taxi' is 택시를 타다; 'hail one' is 택시를 잡다.", example: { ko: "늦어서 택시를 탔어요.", en: "I was late, so I took a taxi.", form: "늦다 → 늦어서 (because); 타다 → 탔어요 (past)" } },
    "l4-noun-yeol-cha": { note: "A train, a slightly formal word heard in announcements. In speech, 기차 is more common, and the subway is 지하철.", example: { ko: "열차가 곧 도착합니다.", en: "The train is arriving soon.", form: "도착하다 → 도착합니다 (formal, as in announcements)" } },
    "l4-noun-yeok": { note: "A station, for trains or the subway. It follows the name: 서울역, 강남역.", example: { ko: "역까지 걸어서 가요.", en: "I walk to the station.", form: "역 + 까지 (up to); 걷다 → 걸어서 (on foot)" } },
    "l4-noun-beo-seu jeong-ryu-jang": { note: "A bus stop: 버스 + 정류장 (stop, station). 정류장 alone often means the bus stop.", example: { ko: "버스 정류장이 어디에 있어요?", en: "Where is the bus stop?", form: "정류장 + 이 (subject); 어디 + 에 (where)" } },
    "l4-noun-bi-haeng-gi": { note: "An airplane: 비행 (flight) + 기 (machine). 'Fly somewhere' is 비행기로 가다 or 비행기를 타다.", example: { ko: "비행기를 타고 한국에 가요.", en: "I take a plane to Korea.", form: "타다 → 타고 (and then); 한국 + 에 (destination)" } },
    "l4-noun-ja-jeon-geo": { note: "A bicycle. Riding one is 자전거를 타다, the same verb as for cars and buses.", example: { ko: "주말에 자전거를 타요.", en: "I ride my bike on weekends.", form: "자전거 + 를 (object); 타다 → 타요" } },
    "l4-noun-a-nae": { note: "Wife: your own, or in formal speech. Someone else's wife is 부인; a husband says 집사람 or 와이프 in casual speech.", example: { ko: "제 아내는 선생님이에요.", en: "My wife is a teacher.", form: "제 (my) + 아내 + 는 (topic); 선생님 + 이에요" } },
    "l4-noun-a-i": { note: "A child. It is often shortened to 애 in speech. 아이들 is 'children'.", example: { ko: "아이가 공원에서 놀아요.", en: "The child is playing in the park.", form: "공원 + 에서 (place of an action); 놀다 → 놀아요" } },
    "l4-noun-a-deul": { note: "A son. 'Only son' is 외아들.", example: { ko: "아들이 두 명 있어요.", en: "I have two sons.", form: "두 명 (two people, native number + counter); 있다 → 있어요" } },
    "l4-noun-ddal": { note: "A daughter. The ㄸ is tense: say it tight, not like 탈 or 달.", example: { ko: "제 딸은 다섯 살이에요.", en: "My daughter is five years old.", form: "다섯 살 (five years old: native number + 살)" } },
    "l4-noun-nam-pyeon": { note: "Husband. Someone else's husband is politely 남편분 or 바깥분.", example: { ko: "남편은 회사에서 일해요.", en: "My husband works at a company.", form: "회사 + 에서 (place of an action); 일하다 → 일해요" } },
    "l4-noun-a-beo-ji": { note: "Father. 아빠 is 'dad'; the honorific is 아버님.", example: { ko: "아버지는 신문을 읽으세요.", en: "My father reads the newspaper.", form: "읽다 → 읽으세요 (honorific -(으)시- for a parent)" } },
    "l4-noun-eo-meo-ni": { note: "Mother. 엄마 is 'mom'; the honorific is 어머님. 어머니 is also a polite way to address a middle-aged woman.", example: { ko: "어머니가 요리를 하세요.", en: "My mother is cooking.", form: "하다 → 하세요 (honorific present)" } },
    "l4-noun-pyeon-ji": { note: "A letter you send. 'Write a letter' is 편지를 쓰다. A letter of the alphabet is 글자.", example: { ko: "친구에게 편지를 써요.", en: "I write a letter to my friend.", form: "친구 + 에게 (to a person); 쓰다 → 써요 (ㅡ drops)" } },
    "l4-noun-mas": { note: "Taste or flavor. It builds 맛있다 (delicious) and 맛없다 (not tasty); 'try it' is 맛을 보다.", example: { ko: "이 국은 맛이 이상해요.", en: "This soup tastes strange.", form: "맛 + 이 (subject); 이상하다 → 이상해요" } },
    "l4-noun-sik-sa": { note: "A meal, a polite and slightly formal word. 식사하셨어요? (Have you eaten?) is a common polite greeting.", example: { ko: "식사하셨어요?", en: "Have you eaten?", form: "식사하다 → 식사하셨어요 (honorific past: -시- + -었-)" } },
    "l4-noun-a-chim": { note: "Morning, and also breakfast by itself: 아침 먹었어요? is 'did you have breakfast?'", example: { ko: "아침에 일찍 일어나요.", en: "I get up early in the morning.", form: "아침 + 에 (time); 일어나다 → 일어나요" } },
    "l4-noun-a-chim-sik-sa": { note: "Breakfast, the polite full form. In speech, 아침 alone is more common: 아침 먹었어요?", example: { ko: "아침식사는 7시부터예요.", en: "Breakfast is from 7 o'clock.", form: "7시 + 부터 (from); 이다 → 예요" } },
    "l4-noun-mul": { note: "Water. 'Drink water' is 물을 마시다; cold water is 찬물, hot water 뜨거운 물.", example: { ko: "물 좀 주세요.", en: "Some water, please.", form: "물 + 좀 (a little, softens a request); 주다 → 주세요" } },
    "l4-noun-sa-goa": { note: "An apple. The same spelling also means an apology: 사과하다 is 'to apologize'.", example: { ko: "사과 세 개 주세요.", en: "Three apples, please.", form: "세 개 (three, native number + counter for things)" } },
    "l4-noun-don": { note: "Money. 'Make money' is 돈을 벌다, 'spend money' 돈을 쓰다.", example: { ko: "돈이 없어요.", en: "I don't have money.", form: "돈 + 이 (subject); 없다 → 없어요" } },
    "l4-verb-ggeut-na-da": { note: "For something to end or be over, by itself: 수업이 끝나다. When someone finishes something, use 끝내다.", example: { ko: "수업이 끝났어요.", en: "Class is over.", form: "수업 + 이 (subject); 끝나다 → 끝났어요 (past)" } },
    "l4-verb-o-da": { note: "To come; also for rain or snow falling: 비가 와요. Its past is 왔어요.", example: { ko: "비가 와요.", en: "It's raining.", form: "비 + 가 (subject); 오다 → 와요 (오 + 아 → 와)" } },
    "l4-verb-ggeut-nae-da": { note: "To finish something, with 을/를: 일을 끝내다. Compare 끝나다, where the thing ends by itself.", example: { ko: "숙제를 끝냈어요.", en: "I finished my homework.", form: "숙제 + 를 (object); 끝내다 → 끝냈어요 (past)" } },
    "l4-verb-chum-chu-da": { note: "To dance: 춤 (a dance) + 추다 (to dance). You can also say 춤을 추다.", example: { ko: "친구들과 춤을 췄어요.", en: "I danced with my friends.", form: "친구들 + 과 (with); 추다 → 췄어요 (우 + 었 → 웠)" } },
    "l4-verb-al-da": { note: "To know a fact or a person. It is an ㄹ stem: 압니다, 아세요. 'I don't know' is 몰라요 (모르다), never 안 알아요.", example: { ko: "그 사람을 알아요?", en: "Do you know that person?", form: "사람 + 을 (object); 알다 → 알아요" } },
    "l4-verb-geot-da": { note: "To walk. The ㄷ turns into ㄹ before a vowel: 걸어요, 걸었어요. 걸어서 means 'on foot'. (걷다 'to tuck/roll up' in Lesson 7 is regular.)", example: { ko: "학교까지 걸어서 가요.", en: "I walk to school.", form: "걷다 → 걸어서 (ㄷ irregular; on foot)" } },
    "l4-verb-bae-u-da": { note: "To learn, with 을/를. 'Learn from someone' uses 에게서 or 한테서.", example: { ko: "한국어를 배우고 있어요.", en: "I'm learning Korean.", form: "배우다 + -고 있어요 (ongoing action)" } },
    "l4-verb-yeon-seup-ha-da": { note: "To practice, with 을/를: 피아노를 연습하다.", example: { ko: "매일 발음을 연습해요.", en: "I practice pronunciation every day.", form: "발음 + 을 (object); 연습하다 → 연습해요" } },
    "l4-verb-saeng-gak-ha-da": { note: "To think. 'Think of / about' is 을/를 생각하다 or 에 대해 생각하다; 'I think that…' is …다고 생각해요.", example: { ko: "가족을 자주 생각해요.", en: "I often think about my family.", form: "가족 + 을 (object); 생각하다 → 생각해요" } },
    "l4-verb-sal-da": { note: "To live somewhere (with 에, or 에서) or simply to be alive. It is an ㄹ stem: 사세요, 삽니다.", example: { ko: "어디에 살아요?", en: "Where do you live?", form: "어디 + 에 (location); 살다 → 살아요" } },
    "l4-adjective-ui-heom-ha-da": { note: "To be dangerous. 위험해요! works on its own as 'Watch out!'", example: { ko: "밤에 혼자 걷는 것은 위험해요.", en: "Walking alone at night is dangerous.", form: "걷다 → 걷는 것 (walking, as a noun); 위험하다 → 위험해요" } },
    "l4-adjective-jal-saeng-gi-da": { note: "To be good-looking, usually for men: 잘 (well) + 생기다 (to be formed). It is said in the past form: 잘생겼어요.", example: { ko: "그 배우는 정말 잘생겼어요.", en: "That actor is really handsome.", form: "잘생기다 → 잘생겼어요 (past form for a present state)" } },
    "l4-adjective-mos-saeng-gi-da": { note: "To be ugly: 못 (badly) + 생기다. Rude about a person; like 잘생기다, it takes the past form: 못생겼어요.", example: { ko: "이 인형은 못생겼지만 귀여워요.", en: "This doll is ugly but cute.", form: "못생기다 → 못생겼지만 (past + -지만, but)" } },
    "l4-adjective-pi-gon-ha-da": { note: "To be tired. Saying 피곤해요 is a normal way to explain why you can't do something.", example: { ko: "오늘 너무 피곤해요.", en: "I'm so tired today.", form: "피곤하다 → 피곤해요 (하 + 여 → 해)" } },
    "l4-adjective-da-reu-da": { note: "To be different, with 와/과 or 하고 for 'different from'. 르 irregular: 달라요. It is not 'wrong', which is 틀리다, though Koreans mix them up in speech.", example: { ko: "한국어는 영어와 달라요.", en: "Korean is different from English.", form: "영어 + 와 (from/with); 다르다 → 달라요 (르 irregular)" } },
    "l4-adjective-seul-peu-da": { note: "To be sad. It describes how something is (슬픈 영화) or how you feel; 'someone looks sad' is 슬퍼 보이다.", example: { ko: "그 영화는 너무 슬퍼요.", en: "That movie is so sad.", form: "슬프다 → 슬퍼요 (ㅡ drops before -어요)" } },
    "l4-adjective-mas-iss-da": { note: "To be tasty: 맛 (taste) + 있다. It is pronounced 마싣따. Its opposite is 맛없다.", example: { ko: "김치가 맛있어요.", en: "The kimchi is delicious.", form: "김치 + 가 (subject); 맛있다 → 맛있어요" } },
    "l4-adjective-jae-mi-iss-da": { note: "To be fun or interesting: 재미 (fun) + 있다. Its opposite is 재미없다 (boring).", example: { ko: "한국어 공부는 재미있어요.", en: "Studying Korean is fun.", form: "공부 + 는 (topic); 재미있다 → 재미있어요" } },
    "l4-adjective-manh-da": { note: "To be many or much: the thing is the subject (사람이 많다). The ㅎ is silent before a vowel: 많아요 sounds like 마나요.", example: { ko: "명동에는 사람이 많아요.", en: "There are a lot of people in Myeongdong.", form: "사람 + 이 (subject); 많다 → 많아요" } },
    "l4-adjective-haeng-bok-ha-da": { note: "To be happy, a deep, lasting happiness. For a moment of joy, 기쁘다 is more natural.", example: { ko: "가족과 함께 있어서 행복해요.", en: "I'm happy because I'm with my family.", form: "있다 → 있어서 (because); 행복하다 → 행복해요" } },
    "l4-adverb-geo-gi": { note: "'There', near the listener or a place just mentioned. It sits between 여기 (here) and 저기 (over there).", example: { ko: "거기 날씨는 어때요?", en: "How is the weather there?", form: "거기 + 날씨 (there's weather); 어떻다 → 어때요" } },
    "l4-adverb-jeo-gi": { note: "'Over there', far from both of you, often with pointing. 저기요 is also a polite 'excuse me' to get attention.", example: { ko: "저기에 은행이 있어요.", en: "There's a bank over there.", form: "저기 + 에 (location); 있다 → 있어요" } },
    "l4-adverb-ji-geum": { note: "'Now', usually at the start of the sentence or before the verb.", example: { ko: "지금 몇 시예요?", en: "What time is it now?", form: "몇 시 (what hour); 이다 → 예요" } },
    "l4-adverb-ha-ji-man": { note: "'But / however', starting a new sentence. Inside one sentence, attach -지만 to the verb instead: 비싸지만.", example: { ko: "비싸요. 하지만 맛있어요.", en: "It's expensive. But it's tasty.", form: "하지만 opens the second sentence" } },
    "l4-phrase-an-nyeong-hi ga-se-yo": { note: "'Goodbye' to the person who is leaving: literally 'go in peace'. If you are both leaving, both say 안녕히 가세요.", example: { ko: "안녕히 가세요. 내일 봐요!", en: "Goodbye. See you tomorrow!", form: "가다 → 가세요 (honorific request); 보다 → 봐요" } },
    "l4-phrase-an-nyeong-hi gye-se-yo": { note: "'Goodbye' said by you when you leave and the other person stays: literally 'stay in peace' (계시다 is honorific 있다).", example: { ko: "사장님, 안녕히 계세요.", en: "Goodbye, sir. (as I leave)", form: "계시다 → 계세요 (honorific of 있다)" } },
    "l4-phrase-man-na-seo ban-gap-seup-ni-da": { note: "'Nice to meet you': 만나다 + -아서 (because) + 반갑다 (to be glad). With friends, 만나서 반가워.", example: { ko: "처음 뵙겠습니다. 만나서 반갑습니다.", en: "How do you do? Nice to meet you.", form: "반갑다 → 반갑습니다 (formal polite)" } },
    "l4-phrase-sil-rye-hap-ni-da": { note: "'Excuse me': for getting past someone, entering a room, or interrupting. It is pronounced 실례함니다. To call a waiter, use 저기요.", example: { ko: "실례합니다. 화장실이 어디예요?", en: "Excuse me. Where is the restroom?", form: "실례하다 → 실례합니다 (formal polite)" } },
    "l4-phrase-joi-song-hap-ni-da/mi-an-hap-ni-da": { note: "'Sorry'. 죄송합니다 is the humble, more formal apology for elders, customers and strangers; 미안합니다 is for equals; 미안해 for friends.", example: { ko: "늦어서 죄송합니다.", en: "I'm sorry I'm late.", form: "늦다 → 늦어서 (because); 죄송하다 → 죄송합니다" } },
    "l4-phrase-je-bal": { note: "'Please', but only for begging or pleading. An ordinary polite request uses -아/어 주세요 instead.", example: { ko: "제발 조용히 해 주세요.", en: "Please, be quiet.", form: "조용히 하다 → 해 주세요 (please do); 제발 adds pleading" } },
    "l4-phrase-i-reum-i mueo-ye-yo?": { note: "'What's your name?': 이름 + 이 + 뭐예요. To someone older, ask 성함이 어떻게 되세요? instead.", example: { ko: "이름이 뭐예요? — 제 이름은 지수예요.", en: "What's your name? — My name is Jisu.", form: "뭐 (what) + 예요 (이다 after a vowel)" } },
    "l4-phrase-jeo-eui i-reum-eun ______i-da": { note: "'My name is ___', written in the dictionary form. In speech it's 제 이름은 ___이에요/예요, and 저의 shortens to 제.", example: { ko: "제 이름은 마이클이에요.", en: "My name is Michael.", form: "저의 → 제; 이다 → 이에요 (after a batchim)" } },
    "l4-phrase-eo-di-e-seo oass-eo-yo?": { note: "'Where are you from?', literally 'where did you come from?': 어디 + 에서 (from) + 오다 in the past.", example: { ko: "어디에서 왔어요? — 미국에서 왔어요.", en: "Where are you from? — I'm from the US.", form: "오다 → 왔어요 (past); 에서 marks the starting place" } },
    "l4-phrase-jeo-neun _______e-seo oass-eo-yo": { note: "'I am from ___': fill the blank with a country or city, and 에서 marks it as where you came from.", example: { ko: "저는 캐나다에서 왔어요.", en: "I'm from Canada.", form: "캐나다 + 에서 (from); 오다 → 왔어요 (past)" } },
    "l4-adverb-do": { note: "'Too / also', a particle that replaces 은/는, 이/가 and 을/를: 저도, 커피도. It attaches straight to the noun.", example: { ko: "저도 커피를 좋아해요.", en: "I like coffee too.", form: "저 + 도 (replaces 는); 좋아하다 → 좋아해요" } },

    // ============================================================== lesson 5
    "l5-noun-dong-saeng": { note: "A younger sibling of either sex. Add 남- or 여- to be specific. It's also used for any younger friend you're close to.", example: { ko: "동생이 한 명 있어요.", en: "I have one younger sibling.", form: "한 명 (one person: native number + counter)" } },
    "l5-noun-nam-dong-saeng": { note: "A younger brother: 남 (male) + 동생. The same word whether you are a man or a woman.", example: { ko: "제 남동생은 고등학생이에요.", en: "My younger brother is a high-school student.", form: "남동생 + 은 (topic); 고등학생 + 이에요" } },
    "l5-noun-yeo-dong-saeng": { note: "A younger sister: 여 (female) + 동생.", example: { ko: "여동생이 저보다 키가 커요.", en: "My younger sister is taller than me.", form: "저 + 보다 (than); 키가 크다 → 커요 (to be tall)" } },
    "l5-noun-hyeong": { note: "What a male calls his older brother, and also a close older male friend. Speaking politely about someone else's: 형님.", example: { ko: "형, 같이 가요!", en: "Hyung, let's go together!", form: "형 used as a form of address; 가다 → 가요 (suggestion)" } },
    "l5-noun-o-bba": { note: "What a female calls her older brother, and also an older male friend or boyfriend.", example: { ko: "오빠는 서울에 살아요.", en: "My older brother lives in Seoul.", form: "서울 + 에 (location); 살다 → 살아요" } },
    "l5-noun-nu-na": { note: "What a male calls his older sister, and also a close older female friend.", example: { ko: "누나가 저에게 선물을 줬어요.", en: "My older sister gave me a present.", form: "저 + 에게 (to me); 주다 → 줬어요 (past)" } },
    "l5-noun-eon-ni": { note: "What a female calls her older sister, and also a close older female friend. Women also use it for young female shop staff.", example: { ko: "언니하고 쇼핑을 했어요.", en: "I went shopping with my older sister.", form: "언니 + 하고 (with); 하다 → 했어요 (past)" } },
    "l5-noun-sam-chon": { note: "An uncle, most often the father's younger, unmarried brother. The mother's brother is 외삼촌.", example: { ko: "삼촌은 부산에 살아요.", en: "My uncle lives in Busan.", form: "부산 + 에 (location); 살다 → 살아요" } },
    "l5-noun-i-mo": { note: "Your mother's sister. People also call a friendly older woman running a restaurant 이모.", example: { ko: "이모, 여기 김치 좀 더 주세요.", en: "Ma'am, more kimchi here please.", form: "이모 used for a restaurant owner; 주다 → 주세요" } },
    "l5-noun-go-mo": { note: "Your father's sister. Her husband is 고모부.", example: { ko: "고모는 의사예요.", en: "My aunt (dad's sister) is a doctor.", form: "고모 + 는 (topic); 의사 + 예요" } },
    "l5-noun-a-jeo-ssi": { note: "A middle-aged man you're not related to, as a way to address or mention him. Young men may not like being called this.", example: { ko: "아저씨, 이거 얼마예요?", en: "Sir, how much is this?", form: "아저씨 as a form of address; 얼마 (how much) + 예요" } },
    "l5-noun-a-ju-meo-ni": { note: "A middle-aged woman you're not related to. 아줌마 is the common casual form, but it can sound rude; 사장님 or 이모 are friendlier in shops.", example: { ko: "아주머니, 물 좀 주세요.", en: "Ma'am, some water please.", form: "물 + 좀 (a little); 주다 → 주세요" } },
    "l5-noun-hal-a-beo-ji": { note: "Grandfather, and a polite term for any elderly man. The mother's father may be 외할아버지.", example: { ko: "할아버지는 매일 산책하세요.", en: "My grandfather takes a walk every day.", form: "산책하다 → 산책하세요 (honorific present for an elder)" } },
    "l5-noun-hal-meo-ni": { note: "Grandmother, and a polite term for any elderly woman. The mother's mother may be 외할머니.", example: { ko: "할머니가 김치를 만드셨어요.", en: "My grandmother made kimchi.", form: "만들다 → 만드셨어요 (honorific past; ㄹ drops before ㅅ)" } },
    "l5-noun-chin-gu": { note: "A friend, but strictly someone your own age; an older friend is 형/오빠/누나/언니. 친구 also means 'buddy' when addressing a child.", example: { ko: "친구와 영화를 봤어요.", en: "I watched a movie with a friend.", form: "친구 + 와 (with); 보다 → 봤어요 (past)" } },
    "l5-noun-sa-jin": { note: "A photo or picture. 'Take a photo' is 사진을 찍다. A drawn picture is 그림.", example: { ko: "사진 좀 찍어 주세요.", en: "Please take a photo (of us).", form: "찍다 → 찍어 + 주세요 (please do it for me)" } },
    "l5-noun-an-gyeong": { note: "Glasses (spectacles). Wearing them is 안경을 쓰다; sunglasses are 선글라스.", example: { ko: "저는 안경을 써요.", en: "I wear glasses.", form: "안경 + 을 (object); 쓰다 → 써요 (ㅡ drops)" } },
    "l5-noun-bi-mil": { note: "A secret. 비밀이에요 means 'it's a secret'; 비밀번호 is a password.", example: { ko: "이건 우리 비밀이에요.", en: "This is our secret.", form: "이건 = 이것은; 비밀 + 이에요" } },
    "l5-noun-bi": { note: "Rain. It 'comes': 비가 오다 (it rains). 'Get rained on' is 비를 맞다.", example: { ko: "오늘 비가 와요.", en: "It's raining today.", form: "비 + 가 (subject); 오다 → 와요" } },
    "l5-noun-ga-ge": { note: "A store or shop, especially a small one. A convenience store is 편의점; a department store is 백화점.", example: { ko: "가게에서 우유를 샀어요.", en: "I bought milk at the store.", form: "가게 + 에서 (place of an action); 사다 → 샀어요" } },
    "l5-noun-bak-mul-goan": { note: "A museum. An art museum is 미술관.", example: { ko: "주말에 박물관에 갔어요.", en: "I went to a museum on the weekend.", form: "박물관 + 에 (destination); 가다 → 갔어요" } },
    "l5-noun-ga-seu re-in-ji": { note: "A gas stove (from 'gas range'). Turning it on is 켜다, off is 끄다.", example: { ko: "가스 레인지를 꼭 끄세요.", en: "Be sure to turn off the stove.", form: "꼭 (be sure to); 끄다 → 끄세요 (polite request)" } },
    "l5-noun-o-ri": { note: "A duck. 오리고기 is duck meat, a popular dish.", example: { ko: "호수에 오리가 있어요.", en: "There are ducks on the lake.", form: "호수 + 에 (location); 오리 + 가 (subject)" } },
    "l5-noun-ggo-ri": { note: "An animal's tail. 'Wag its tail' is 꼬리를 흔들다.", example: { ko: "강아지가 꼬리를 흔들어요.", en: "The puppy is wagging its tail.", form: "꼬리 + 를 (object); 흔들다 → 흔들어요" } },
    "l5-verb-bo-go-sip-da": { note: "'To miss someone': literally 'want to see' (보다 + -고 싶다). Usually spelled with a space, 보고 싶다. For missing a thing or place, 그립다 is common.", example: { ko: "엄마가 보고 싶어요.", en: "I miss my mom.", form: "보고 싶다 → 보고 싶어요; the person missed takes 이/가 or 을/를" } },
    "l5-verb-gi-dae-ha-da": { note: "To expect, or look forward to something: 기대돼요 is 'I'm excited for it'.", example: { ko: "여행을 기대하고 있어요.", en: "I'm looking forward to the trip.", form: "기대하다 + -고 있어요 (ongoing)" } },
    "l5-verb-geon-neo-da": { note: "To cross (a road, a bridge, a river), with 을/를. A crosswalk is 횡단보도.", example: { ko: "길을 건널 때 조심하세요.", en: "Be careful when you cross the road.", form: "건너다 → 건널 때 (when crossing); 조심하다 → 조심하세요" } },
    "l5-verb-silh-eo-ha-da": { note: "To dislike, with 을/를: 고양이를 싫어해요. It describes someone's dislike; for your own feeling, 싫다 is more direct.", example: { ko: "제 동생은 채소를 싫어해요.", en: "My younger sibling doesn't like vegetables.", form: "채소 + 를 (object); 싫어하다 → 싫어해요" } },
    "l5-verb-ddeo-na-da": { note: "To leave a place for good or for a trip (한국을 떠나다), and also to set off (여행을 떠나다). Leaving work for the day is 퇴근하다.", example: { ko: "내일 한국을 떠나요.", en: "I'm leaving Korea tomorrow.", form: "한국 + 을 (the place left takes 을/를); 떠나다 → 떠나요" } },
    "l5-verb-nong-dam-ha-da": { note: "To joke. 농담이에요 is 'just kidding'.", example: { ko: "농담하지 마세요!", en: "Don't joke around!", form: "농담하다 + -지 마세요 (please don't)" } },
    "l5-verb-deon-ji-da": { note: "To throw something, with 을/를. 'Throw it to me' is 저에게 던져 주세요.", example: { ko: "공을 던져 주세요.", en: "Please throw the ball.", form: "던지다 → 던져 + 주세요 (ㅣ + 어 → ㅕ)" } },
    "l5-adjective-ji-ru-ha-da": { note: "To be boring, of a thing or of you feeling bored. 지루해요 can mean either 'it's boring' or 'I'm bored'.", example: { ko: "이 수업은 너무 지루해요.", en: "This class is so boring.", form: "지루하다 → 지루해요" } },
    "l5-adjective-ma-reu-da": { note: "For a person to be very thin, often too thin: 말랐어요, said in the past form like 잘생기다. 르 irregular: 말라요.", example: { ko: "그 사람은 너무 말랐어요.", en: "That person is too thin.", form: "마르다 → 말랐어요 (르 irregular, past for a state)" } },
    "l5-adjective-meol-da": { note: "To be far, with 에서 for 'far from'. Its opposite is 가깝다. ㄹ stem: 먼 곳 (a far place).", example: { ko: "집에서 학교까지 멀어요.", en: "It's far from my house to school.", form: "에서 … 까지 (from … to); 멀다 → 멀어요" } },
    "l5-adjective-ma-reu-da-dry": { note: "To be dry, or to dry out: 목이 마르다 is 'to be thirsty'. 르 irregular: 말라요.", example: { ko: "목이 말라요.", en: "I'm thirsty.", form: "목 (throat) + 이; 마르다 → 말라요 (르 irregular)" } },
    "l5-adjective-bi-seus-ha-da": { note: "To be similar, with 와/과 or 하고: 'similar to'. 똑같다 is 'exactly the same'.", example: { ko: "제 가방은 친구 가방과 비슷해요.", en: "My bag is similar to my friend's bag.", form: "가방 + 과 (to/with); 비슷하다 → 비슷해요" } },
    "l5-adjective-silh-da": { note: "To be disliked, or for you to not want something. The thing is the subject: 비가 싫어요 (I don't like rain). Alone, 싫어요! is a flat 'No, I don't want to!'", example: { ko: "저는 비 오는 날이 싫어요.", en: "I don't like rainy days.", form: "날 + 이 (subject); 싫다 → 싫어요" } },
    "l5-adjective-o-rae-doi-da": { note: "For a thing to be old, to have existed a long time: 오래된 건물. For people, use 늙다 or 나이가 많다; for worn-out things, 낡다.", example: { ko: "이 건물은 아주 오래됐어요.", en: "This building is very old.", form: "오래되다 → 오래됐어요 (되었 → 됐, past for a state)" } },
    "l5-adverb-o-neul": { note: "Today. Time words like this don't need 에: 오늘 가요, not 오늘에 가요.", example: { ko: "오늘 시간 있어요?", en: "Do you have time today?", form: "오늘 (no 에); 시간 + (이) 있다 → 있어요?" } },
    "l5-adverb-ueol-yo-il": { note: "Monday: 월 (moon) + 요일 (day of the week). Days take 에: 월요일에.", example: { ko: "월요일에 수업이 있어요.", en: "I have class on Monday.", form: "월요일 + 에 (time); 수업 + 이 있다" } },
    "l5-adverb-hoa-yo-il": { note: "Tuesday: 화 (fire) + 요일.", example: { ko: "화요일에 친구를 만나요.", en: "I meet my friend on Tuesday.", form: "화요일 + 에 (time); 만나다 → 만나요" } },
    "l5-adverb-su-yo-il": { note: "Wednesday: 수 (water) + 요일.", example: { ko: "수요일은 바빠요.", en: "Wednesdays are busy.", form: "수요일 + 은 (topic); 바쁘다 → 바빠요" } },
    "l5-adverb-mok-yo-il": { note: "Thursday: 목 (wood/tree) + 요일.", example: { ko: "목요일에 시험이 있어요.", en: "I have a test on Thursday.", form: "목요일 + 에 (time); 시험 + 이 있다" } },
    "l5-adverb-geum-yo-il": { note: "Friday: 금 (gold/metal) + 요일. 불금 (불타는 금요일) is slang for a fun Friday night.", example: { ko: "금요일 저녁에 뭐 해요?", en: "What are you doing Friday evening?", form: "금요일 + 저녁 + 에 (time); 하다 → 해요" } },
    "l5-adverb-to-yo-il": { note: "Saturday: 토 (earth) + 요일. The weekend is 주말.", example: { ko: "토요일에는 늦게 일어나요.", en: "On Saturdays I get up late.", form: "토요일 + 에 + 는 (time + topic); 일어나다 → 일어나요" } },
    "l5-adverb-il-yo-il": { note: "Sunday: 일 (sun) + 요일.", example: { ko: "일요일에 교회에 가요.", en: "I go to church on Sunday.", form: "일요일 + 에 (time); 교회 + 에 (destination)" } },
    "l5-adverb-eo-je": { note: "Yesterday. Like 오늘 and 내일, it doesn't take 에.", example: { ko: "어제 뭐 했어요?", en: "What did you do yesterday?", form: "어제 (no 에); 하다 → 했어요 (past)" } },
    "l5-adverb-nae-il": { note: "Tomorrow. Like 오늘, it doesn't take 에. 내일 봐요 is 'see you tomorrow'.", example: { ko: "내일 만나요.", en: "Let's meet tomorrow.", form: "내일 (no 에); 만나다 → 만나요 (suggestion)" } },
    "l5-adverb-mo-re": { note: "The day after tomorrow. The day before yesterday is 그저께 (or 그제).", example: { ko: "모레 한국에 가요.", en: "I'm going to Korea the day after tomorrow.", form: "모레 (no 에); 가다 → 가요" } },
    "l5-adverb-nyeon": { note: "Year, as a counter with Sino-Korean numbers: 2025년, 3년 (three years). The word 'year' alone is 해: 올해 (this year).", example: { ko: "저는 한국에서 3년 살았어요.", en: "I lived in Korea for three years.", form: "3년 (삼 년, Sino-Korean number + counter); 살다 → 살았어요" } },
    "l5-adverb-il": { note: "Day, as a counter with Sino-Korean numbers: 5일 (the 5th, or five days). A plain 'day' is 날.", example: { ko: "제 생일은 5월 3일이에요.", en: "My birthday is May 3rd.", form: "5월 (오월) 3일 (삼일): Sino-Korean numbers for dates" } },
    "l5-adverb-si-gan": { note: "Time, and also 'hour(s)' as a counter with native numbers: 두 시간 (two hours). 'What time is it?' uses 시 instead: 몇 시예요?", example: { ko: "한국어를 두 시간 공부했어요.", en: "I studied Korean for two hours.", form: "두 시간 (native number + 시간 for duration)" } },
    "l5-noun-nae-ga": { note: "'I' as a subject in casual speech: 나 + 가 becomes 내가, never 나가. Polite: 제가.", example: { ko: "내가 할게.", en: "I'll do it.", form: "나 + 가 → 내가; 하다 → 할게 (I will, casual)" } },
    "l5-noun-je-ga": { note: "'I' as a subject, politely: 저 + 가 becomes 제가. It's how you volunteer or stress that it's you.", example: { ko: "제가 하겠습니다.", en: "I will do it.", form: "저 + 가 → 제가; 하다 → 하겠습니다 (formal, will)" } },
    "l5-noun-neo": { note: "'You' for close friends and younger people only. Adults avoid 'you' with anyone else; use their name or title.", example: { ko: "너는 어디 가?", en: "Where are you going?", form: "너 + 는 (topic); 가다 → 가 (casual speech)" } },
    "l5-noun-ne-ga": { note: "'You' as a subject in casual speech: 너 + 가 becomes 네가. In speech it is often said 니가 to avoid confusion with 내가.", example: { ko: "네가 제일 좋아.", en: "I like you the most.", form: "너 + 가 → 네가 (said 니가); 좋다 → 좋아 (casual)" } },
    "l5-noun-dang-sin": { note: "'You' that is rarely used in conversation: it can sound rude or confrontational. Married couples use it for 'honey', and it appears in songs, ads and writing.", example: { ko: "당신을 사랑해요.", en: "I love you. (as in a song or to a spouse)", form: "당신 + 을 (object); 사랑하다 → 사랑해요" } },
    "l5-noun-bu-jang-nim": { note: "A department head at a company, with -님. Koreans call colleagues by title, not name: 부장님, 과장님, 팀장님.", example: { ko: "부장님, 회의는 몇 시예요?", en: "Sir/Ma'am, what time is the meeting?", form: "부장님 as a form of address; 몇 시 (what time) + 예요" } },
    "l5-noun-gyo-jang-seon-saeng-nim": { note: "A school principal: 교장 + 선생님. It's often shortened to 교장님.", example: { ko: "교장선생님이 오셨어요.", en: "The principal has arrived.", form: "오다 → 오셨어요 (honorific past)" } },
    "l5-noun-gyo-gam-seon-saeng-nim": { note: "A vice principal: 교감 + 선생님, often 교감님.", example: { ko: "교감선생님은 교무실에 계세요.", en: "The vice principal is in the teachers' office.", form: "있다 → 계시다 → 계세요 (honorific 'to be at')" } },
    "l5-noun-go-gaek-nim": { note: "'Customer' as staff address you: 고객 + -님. You'll hear it in banks, shops and phone service.", example: { ko: "고객님, 잠시만 기다려 주세요.", en: "Please wait a moment, sir/ma'am.", form: "잠시만 (just a moment); 기다리다 → 기다려 주세요" } },
    "l5-noun-son-nim": { note: "A guest or customer, the most common way shop and restaurant staff refer to you.", example: { ko: "손님, 몇 분이세요?", en: "How many people are in your party?", form: "몇 분 (how many people, honorific counter); 이시다 → 이세요" } },
    "l5-noun-hoi-jang-nim": { note: "A company chairman, the top of a large company (above 사장님).", example: { ko: "회장님이 회의에 오십니다.", en: "The chairman is coming to the meeting.", form: "오다 → 오십니다 (honorific formal)" } },
    "l5-noun-sa-jang-nim": { note: "A company president or a business owner. Customers also call shop and restaurant owners 사장님 as a friendly courtesy.", example: { ko: "사장님, 계산해 주세요.", en: "Excuse me (owner), the check please.", form: "계산하다 → 계산해 주세요 (please pay/ring up)" } },
    "l5-noun-gong": { note: "A ball. 'Play ball' is 공놀이를 하다. The same spelling is also the Sino-Korean number zero (in phone numbers).", example: { ko: "아이가 공을 차요.", en: "The child kicks the ball.", form: "공 + 을 (object); 차다 → 차요" } },
    "l5-noun-bap": { note: "Cooked rice, and by extension any meal: 밥 먹었어요? is 'have you eaten?' Uncooked rice is 쌀.", example: { ko: "밥 먹었어요?", en: "Have you eaten?", form: "먹다 → 먹었어요 (past); a common greeting" } },
    "l5-verb-gong-bu-ha-da": { note: "To study: 공부 (study) + 하다. Can be split: 한국어를 공부하다 or 한국어 공부를 하다.", example: { ko: "도서관에서 공부해요.", en: "I study at the library.", form: "도서관 + 에서 (place of an action); 공부하다 → 공부해요" } },
    "l5-verb-mo-reu-da": { note: "To not know, the opposite of 알다. 르 irregular: 몰라요, 몰랐어요. Say 몰라요, never 안 알아요.", example: { ko: "저는 그 사람을 몰라요.", en: "I don't know that person.", form: "모르다 → 몰라요 (르 irregular)" } },
    "l5-verb-ba-rae-da": { note: "To fade (color), and in another sense, to see someone off. It is often misused for 바라다 (to hope): 'I hope' is 바라요, not 바래요.", example: { ko: "청바지 색이 바랬어요.", en: "The jeans' color has faded.", form: "바래다 → 바랬어요 (past)" } },
    "l5-verb-mae-da": { note: "To tie, with 을/를: 넥타이를 매다 (put on a tie), 안전벨트를 매다 (fasten a seatbelt).", example: { ko: "안전벨트를 매세요.", en: "Please fasten your seatbelt.", form: "매다 → 매세요 (polite request)" } },
    "l5-verb-me-da": { note: "To carry on the shoulder: 가방을 메다. Not to be confused with 매다 (to tie); the two sound alike.", example: { ko: "학생이 가방을 메고 있어요.", en: "The student is carrying a bag on their shoulder.", form: "메다 + -고 있어요 (state of carrying)" } },
    "l5-verb-jam-geu-da": { note: "To lock: 문을 잠그다. The ㅡ drops: 잠가요, 잠갔어요 (not 잠궈요, a common mistake).", example: { ko: "문을 잠갔어요?", en: "Did you lock the door?", form: "잠그다 → 잠갔어요 (ㅡ drops before -았)" } },
    "l5-verb-na-seo-da": { note: "To step forward or out, and to set out (길을 나서다). It also means to volunteer or come forward.", example: { ko: "아침 일찍 집을 나섰어요.", en: "I left home early in the morning.", form: "집 + 을; 나서다 → 나섰어요 (서 + 었 → 섰)" } },
    "l5-verb-ggi-da": { note: "To put on something that fits snugly: a ring or gloves (반지를 끼다). It also means to be fogged or clouded (안개가 끼다).", example: { ko: "장갑을 꼈어요.", en: "I put on gloves.", form: "끼다 → 꼈어요 (끼 + 었 → 꼈)" } },
    "l5-verb-kyeo-da": { note: "To turn on a light or device: 불을 켜다, TV를 켜다. Its opposite is 끄다.", example: { ko: "불 좀 켜 주세요.", en: "Please turn on the light.", form: "켜다 → 켜 + 주세요" } },
    "l5-verb-doi-da": { note: "To become, with 이/가: 의사가 되다. 되다 is also used for 'to be okay / be possible': 돼요? (Is it okay?)", example: { ko: "저는 선생님이 되고 싶어요.", en: "I want to become a teacher.", form: "선생님 + 이 (what you become); 되다 + -고 싶어요" } },
    "l5-adjective-neulk-da": { note: "For a person or animal to be old or aged. It can sound blunt; 나이가 많다 is more polite. For things, use 낡다 or 오래되다.", example: { ko: "우리 개는 이제 늙었어요.", en: "Our dog is old now.", form: "늙다 → 늙었어요 (past form for a present state)" } },
    "l5-adjective-bae-go-peu-da": { note: "To be hungry: 배 (stomach) + 고프다. Often written with a space, 배가 고프다. The ㅡ drops: 배고파요.", example: { ko: "배고파요. 밥 먹어요!", en: "I'm hungry. Let's eat!", form: "배고프다 → 배고파요 (ㅡ drops before -아요)" } },

    // ============================================================== lesson 6
    "l6-noun-sin-bal": { note: "Shoes in general. Wearing them is 신발을 신다, taking them off 신발을 벗다; Koreans take them off indoors.", example: { ko: "여기서 신발을 벗으세요.", en: "Please take your shoes off here.", form: "벗다 → 벗으세요 (polite request)" } },
    "l6-noun-nam-bang": { note: "A button-up shirt, a slightly old-fashioned word. Younger people say 셔츠.", example: { ko: "아버지가 흰 남방을 입으셨어요.", en: "My father wore a white shirt.", form: "입다 → 입으셨어요 (honorific past)" } },
    "l6-noun-jil-mun": { note: "A question someone asks. 'Ask a question' is 질문하다 or 질문을 하다. A question on a test is 문제.", example: { ko: "질문이 있어요.", en: "I have a question.", form: "질문 + 이 (subject); 있다 → 있어요" } },
    "l6-noun-mun-je": { note: "A problem, or a question on a test or worksheet. 문제없어요 means 'no problem'.", example: { ko: "이 문제는 너무 어려워요.", en: "This question is too hard.", form: "어렵다 → 어려워요 (ㅂ irregular)" } },
    "l6-noun-na-i": { note: "Age. Asking it directly is 몇 살이에요?; to an elder, 연세가 어떻게 되세요?", example: { ko: "나이가 어떻게 되세요?", en: "May I ask your age?", form: "어떻게 되세요? (polite way to ask age, name, etc.)" } },
    "l6-noun-hoa-jang-sil": { note: "A bathroom or restroom (toilet). 화장 means 'makeup', so it's literally a powder room.", example: { ko: "화장실이 어디예요?", en: "Where is the restroom?", form: "화장실 + 이 (subject); 어디 + 예요" } },
    "l6-noun-bun-ui-gi": { note: "The atmosphere or mood of a place or event. 분위기가 좋다 is 'the vibe is nice'.", example: { ko: "이 카페는 분위기가 좋아요.", en: "This café has a nice atmosphere.", form: "카페는 (topic) + 분위기가 (subject); 좋다 → 좋아요" } },
    "l6-noun-cha": { note: "Tea. It shares its spelling with 차 (car); 'drink tea' is 차를 마시다. Green tea is 녹차.", example: { ko: "차 한잔 마실래요?", en: "Would you like a cup of tea?", form: "한잔 (one cup); 마시다 → 마실래요? (do you want to?)" } },
    "l6-noun-ba-ji": { note: "Trousers or pants (one word, not plural). Wearing them is 바지를 입다. Jeans are 청바지.", example: { ko: "이 바지는 너무 길어요.", en: "These pants are too long.", form: "바지 + 는 (topic); 길다 → 길어요" } },
    "l6-noun-gyo-sil": { note: "A classroom. 교실에서 is 'in the classroom' for activities.", example: { ko: "학생들이 교실에 있어요.", en: "The students are in the classroom.", form: "교실 + 에 (location); 있다 → 있어요" } },
    "l6-noun-geup-sik": { note: "Meals served at a school or workplace cafeteria; the lunch everyone gets.", example: { ko: "오늘 급식은 맛있었어요.", en: "Today's school lunch was good.", form: "맛있다 → 맛있었어요 (past)" } },
    "l6-noun-pul": { note: "Glue (paste). The same spelling also means grass and starch. 'Glue it' is 풀로 붙이다.", example: { ko: "풀로 종이를 붙여요.", en: "I stick the paper with glue.", form: "풀 + 로 (with, by means of); 붙이다 → 붙여요" } },
    "l6-noun-su-do": { note: "A capital city. The same spelling also means a water supply or tap (수도꼭지).", example: { ko: "한국의 수도는 서울이에요.", en: "The capital of Korea is Seoul.", form: "한국 + 의 (of); 서울 + 이에요" } },
    "l6-noun-byeong": { note: "A bottle, and also a counter: 맥주 두 병 (two bottles of beer). It shares its spelling with 병 (illness).", example: { ko: "물 한 병 주세요.", en: "A bottle of water, please.", form: "한 병 (one bottle: native number + counter)" } },
    "l6-noun-byeong-disease": { note: "An illness or disease. 'Get sick' is 병에 걸리다 or 병이 나다; a hospital is 병원 (illness + institution).", example: { ko: "할아버지가 병에 걸리셨어요.", en: "My grandfather fell ill.", form: "병 + 에 걸리다 (catch an illness); honorific past -셨-" } },
    "l6-noun-saeng-seon": { note: "Fish as food. A living fish is 물고기.", example: { ko: "저녁에 생선을 구웠어요.", en: "I grilled fish for dinner.", form: "굽다 → 구웠어요 (ㅂ irregular past)" } },
    "l6-noun-ya-chae": { note: "Vegetables. 채소 means the same and is the standard word in writing.", example: { ko: "야채를 많이 드세요.", en: "Eat lots of vegetables.", form: "많이 (a lot); 먹다 → 드세요 (honorific of 먹다)" } },
    "l6-noun-eon-deok": { note: "A hill or slope, smaller than a mountain (산).", example: { ko: "집이 언덕 위에 있어요.", en: "The house is on top of a hill.", form: "언덕 + 위 + 에 (on top of); 있다 → 있어요" } },
    "l6-noun-seon-mul": { note: "A present or gift. 'Give a present' is 선물을 주다; 선물하다 is 'to gift'.", example: { ko: "생일 선물로 책을 받았어요.", en: "I got a book as a birthday present.", form: "선물 + 로 (as); 받다 → 받았어요" } },
    "l6-noun-gi-ta": { note: "A guitar. 'Play the guitar' is 기타를 치다. The same spelling (其他) also means 'other / etc.' on forms.", example: { ko: "저는 기타를 쳐요.", en: "I play the guitar.", form: "기타 + 를 (object); 치다 → 쳐요 (ㅣ + 어 → ㅕ)" } },
    "l6-noun-jong-i": { note: "Paper. Counted with 장: 종이 한 장 (one sheet).", example: { ko: "종이 한 장 주세요.", en: "Please give me a sheet of paper.", form: "한 장 (one sheet: native number + counter)" } },
    "l6-noun-u-yu": { note: "Milk. 'Drink milk' is 우유를 마시다.", example: { ko: "아침마다 우유를 마셔요.", en: "I drink milk every morning.", form: "아침 + 마다 (every); 마시다 → 마셔요" } },
    "l6-noun-son-mok": { note: "The wrist: 손 (hand) + 목 (neck). Likewise 발목 is the ankle.", example: { ko: "손목이 아파요.", en: "My wrist hurts.", form: "손목 + 이 (subject); 아프다 → 아파요" } },
    "l6-noun-si-gye": { note: "A clock or watch. 'Wear a watch' is 시계를 차다.", example: { ko: "시계가 멈췄어요.", en: "The clock has stopped.", form: "멈추다 → 멈췄어요 (past)" } },
    "l6-noun-son-mok-si-gye": { note: "A wristwatch: 손목 (wrist) + 시계 (clock). In speech, 시계 alone usually does.", example: { ko: "손목시계를 선물로 받았어요.", en: "I got a wristwatch as a present.", form: "선물 + 로 (as); 받다 → 받았어요" } },
    "l6-noun-yeong-hoa": { note: "A movie. 'Watch a movie' is 영화를 보다; a cinema is 영화관 or 극장.", example: { ko: "주말에 영화를 봤어요.", en: "I watched a movie on the weekend.", form: "영화 + 를 (object); 보다 → 봤어요" } },
    "l6-verb-no-ryeok-ha-da": { note: "To try hard, to make an effort: 열심히 노력하다. To 'try' something new is -아/어 보다 instead.", example: { ko: "한국어를 잘하려고 노력해요.", en: "I'm trying hard to get good at Korean.", form: "잘하다 + -려고 (in order to); 노력하다 → 노력해요" } },
    "l6-verb-anj-da": { note: "To sit, with 에 for where: 의자에 앉다. The ㄴㅈ batchim sounds like ㄴ alone at the end: 안따. Polite request: 앉으세요.", example: { ko: "여기 앉으세요.", en: "Please sit here.", form: "앉다 → 앉으세요 (polite request; -으세요 after a batchim)" } },
    "l6-verb-man-ji-da": { note: "To touch, with 을/를. 만지지 마세요 is 'Do not touch' on museum signs.", example: { ko: "작품을 만지지 마세요.", en: "Please don't touch the artwork.", form: "만지다 + -지 마세요 (please don't)" } },
    "l6-verb-ja-da": { note: "To sleep. The honorific is 주무시다; 'Good night' is 잘 자 or 안녕히 주무세요.", example: { ko: "저는 보통 11시에 자요.", en: "I usually sleep at 11.", form: "11시 + 에 (time); 자다 → 자요" } },
    "l6-verb-bo-da": { note: "To see, watch or look at. Also 'take' a test (시험을 보다) and, after another verb, 'try doing': 먹어 보다.", example: { ko: "어제 친구와 영화를 봤어요.", en: "I watched a movie with a friend yesterday.", form: "보다 → 봤어요 (보 + 았 → 봤)" } },
    "l6-verb-gi-da-ri-da": { note: "To wait for someone or something, with 을/를: 버스를 기다리다.", example: { ko: "잠깐만 기다려 주세요.", en: "Please wait a moment.", form: "기다리다 → 기다려 + 주세요 (ㅣ + 어 → ㅕ)" } },
    "l6-verb-cheong-so-ha-da": { note: "To clean (a room, a house): 청소 (cleaning) + 하다. Washing dishes is 설거지하다; laundry is 빨래하다.", example: { ko: "주말에 방을 청소해요.", en: "I clean my room on weekends.", form: "방 + 을 (object); 청소하다 → 청소해요" } },
    "l6-verb-yak-sok-ha-da": { note: "To promise. As a noun, 약속 is also a plan or appointment: 약속이 있어요 is 'I have plans'.", example: { ko: "다시 늦지 않겠다고 약속했어요.", en: "I promised I wouldn't be late again.", form: "늦지 않겠다 + -고 (quoting); 약속하다 → 약속했어요" } },
    "l6-verb-deut-da": { note: "To hear or listen to. ㄷ irregular: 들어요, 들었어요. 'Take a class' is also 수업을 듣다.", example: { ko: "음악을 들어요.", en: "I listen to music.", form: "듣다 → 들어요 (ㄷ irregular: ㄷ → ㄹ before a vowel)" } },
    "l6-verb-deul-eo-bo-da": { note: "To (try to) listen to something: 듣다 + 보다 (try). Also 'to hear of': 들어 봤어요? is 'have you heard of it?'", example: { ko: "이 노래 들어 봤어요?", en: "Have you heard this song?", form: "듣다 → 들어 + 보다 (try); past 봤어요" } },
    "l6-verb-geu-man-ha-da": { note: "To stop doing something, or to quit. 그만해! alone is 'Stop it!'", example: { ko: "이제 그만하세요.", en: "Please stop now.", form: "그만하다 → 그만하세요 (polite request)" } },
    "l6-verb-un-dong-ha-da": { note: "To exercise or work out: 운동 (exercise; also 'sport') + 하다.", example: { ko: "저는 매일 아침 운동해요.", en: "I exercise every morning.", form: "매일 아침 (every morning); 운동하다 → 운동해요" } },
    "l6-adjective-nol-ra-da": { note: "To be surprised or startled. It's usually said in the past: 깜짝 놀랐어요 (I was so surprised).", example: { ko: "그 소식을 듣고 깜짝 놀랐어요.", en: "I was so surprised to hear the news.", form: "듣다 → 듣고 (and then); 놀라다 → 놀랐어요" } },
    "l6-adjective-bba-reu-da": { note: "To be fast or quick. 르 irregular: 빨라요. The adverb is 빨리 (quickly).", example: { ko: "지하철이 버스보다 빨라요.", en: "The subway is faster than the bus.", form: "버스 + 보다 (than); 빠르다 → 빨라요 (르 irregular)" } },
    "l6-adjective-neu-ri-da": { note: "To be slow. The adverb is 느리게, or 천천히 for 'slowly' in requests.", example: { ko: "인터넷이 너무 느려요.", en: "The internet is too slow.", form: "느리다 → 느려요 (ㅣ + 어 → ㅕ)" } },
    "l6-adjective-chak-ha-da": { note: "To be kind and good-natured. It's often used for children or partners: 착한 사람 (a good person).", example: { ko: "제 친구는 정말 착해요.", en: "My friend is really kind.", form: "착하다 → 착해요" } },
    "l6-adverb-got": { note: "Soon, before long. 곧 도착합니다 is 'arriving soon'.", example: { ko: "곧 비가 올 거예요.", en: "It's going to rain soon.", form: "오다 → 올 거예요 (will, -(으)ㄹ 거예요)" } },
    "l6-adverb-hang-sang": { note: "Always. 늘 and 언제나 mean the same; 항상 is the most common.", example: { ko: "그 가게는 항상 바빠요.", en: "That store is always busy.", form: "항상 + 바빠요 (바쁘다, ㅡ drops)" } },
    "l6-adverb-ju": { note: "Week, as in 이번 주 (this week), 다음 주 (next week). A counter with Sino-Korean numbers too: 2주 (two weeks).", example: { ko: "다음 주에 시험이 있어요.", en: "There's a test next week.", form: "다음 주 + 에 (time); 시험 + 이 있다" } },
    "l6-adverb-a-rae": { note: "Below or underneath, after a noun with 에: 책상 아래에. Nearly the same as 밑.", example: { ko: "다리 아래에 강이 있어요.", en: "There's a river below the bridge.", form: "다리 + 아래 + 에 (under); 강 + 이" } },
    "l6-noun-jeo-nyeok": { note: "Evening, and also dinner by itself: 저녁 먹었어요?", example: { ko: "저녁에 같이 밥 먹어요.", en: "Let's have a meal together in the evening.", form: "저녁 + 에 (time); 먹다 → 먹어요 (suggestion)" } },

    // ============================================================== lesson 7
    "l7-noun-nun-sseop": { note: "An eyebrow: 눈 (eye) + 썹. An eyelash is 속눈썹.", example: { ko: "그 사람은 눈썹이 진해요.", en: "That person has thick eyebrows.", form: "눈썹 + 이 (subject); 진하다 → 진해요" } },
    "l7-noun-gyo-sa": { note: "A teacher, as a job. You'd say 저는 교사예요 about yourself, but address a teacher as 선생님.", example: { ko: "제 언니는 초등학교 교사예요.", en: "My older sister is an elementary school teacher.", form: "교사 + 예요 (이다 after a vowel)" } },
    "l7-noun-ban": { note: "A class, as a group of students (1학년 3반). The same spelling also means 'half': 한 시 반 (1:30).", example: { ko: "우리 반에는 학생이 스무 명 있어요.", en: "There are twenty students in our class.", form: "스무 명 (twenty people: 스물 → 스무 before a counter)" } },
    "l7-noun-jik-jang": { note: "Your workplace or job. 직장인 is an office worker.", example: { ko: "직장이 집에서 가까워요.", en: "My workplace is close to my house.", form: "집 + 에서 (from); 가깝다 → 가까워요 (ㅂ irregular)" } },
    "l7-noun-byeok": { note: "A wall. Hanging something on it is 벽에 걸다.", example: { ko: "벽에 그림이 있어요.", en: "There's a painting on the wall.", form: "벽 + 에 (location); 그림 + 이 있다" } },
    "l7-noun-teol": { note: "Body hair or an animal's fur. Hair on the head is 머리카락.", example: { ko: "소파에 고양이 털이 많아요.", en: "There's a lot of cat hair on the sofa.", form: "고양이 + 털 (cat's fur); 많다 → 많아요" } },
    "l7-noun-meo-ri-ka-rak": { note: "A hair, or hairs, on the head. For a hairstyle or hair as a whole, 머리 is enough: 머리를 자르다 (get a haircut).", example: { ko: "음식에 머리카락이 있어요.", en: "There's a hair in the food.", form: "음식 + 에 (location); 머리카락 + 이" } },
    "l7-noun-jeom-sim": { note: "Lunch, and also around midday. 점심시간 is lunchtime.", example: { ko: "점심 먹었어요?", en: "Did you have lunch?", form: "먹다 → 먹었어요 (past)" } },
    "l7-noun-os": { note: "Clothes. Wearing them is 옷을 입다; taking them off, 옷을 벗다. The ㅅ sounds like ㄷ at the end: 옫.", example: { ko: "새 옷을 샀어요.", en: "I bought new clothes.", form: "새 (new) + 옷; 사다 → 샀어요" } },
    "l7-verb-chaj-da": { note: "To look for and to find, both. Also to withdraw money (돈을 찾다) and pick up something left (짐을 찾다).", example: { ko: "열쇠를 찾고 있어요.", en: "I'm looking for my keys.", form: "찾다 + -고 있어요 (ongoing)" } },
    "l7-verb-ga-reu-chi-da": { note: "To teach. The subject taught takes 을/를 and the student 에게: 학생에게 영어를 가르치다.", example: { ko: "저는 아이들에게 영어를 가르쳐요.", en: "I teach English to children.", form: "아이들 + 에게 (to); 가르치다 → 가르쳐요" } },
    "l7-verb-il-ha-da": { note: "To work: 일 (work) + 하다. 'Work at X' is X에서 일하다.", example: { ko: "저는 은행에서 일해요.", en: "I work at a bank.", form: "은행 + 에서 (place of an action); 일하다 → 일해요" } },
    "l7-verb-jis-da": { note: "To build, and also to make a name (이름을 짓다), cook rice (밥을 짓다) or write a poem. ㅅ irregular: 지어요.", example: { ko: "할아버지가 이 집을 지으셨어요.", en: "My grandfather built this house.", form: "짓다 → 지으셨어요 (ㅅ drops before a vowel; honorific past)" } },
    "l7-verb-ga-ji-da": { note: "To have or own, with 을/를. In speech it often shortens to 갖다. 가지고 가다/오다 means 'take/bring'.", example: { ko: "우산을 가지고 가세요.", en: "Take an umbrella with you.", form: "가지다 → 가지고 + 가세요 (take it along)" } },
    "l7-verb-ij-da": { note: "To forget. 잊어버리다 adds a sense of 'completely' or regret. Forgetting an object somewhere is often 놓고 오다.", example: { ko: "친구 생일을 잊었어요.", en: "I forgot my friend's birthday.", form: "잊다 → 잊었어요 (past)" } },
    "l7-verb-dop-da": { note: "To help, with 을/를: 친구를 돕다. ㅂ irregular: 도와요 (not 도워요). 도와 주세요 is 'please help me'.", example: { ko: "도와 주세요!", en: "Please help me!", form: "돕다 → 도와 + 주세요 (ㅂ → 오 in this verb)" } },
    "l7-verb-ju-da": { note: "To give, with the person taking 에게 (or 께, honorific). After another verb it means 'do for someone': 해 주세요.", example: { ko: "친구에게 꽃을 줬어요.", en: "I gave flowers to my friend.", form: "친구 + 에게 (to); 주다 → 줬어요 (주 + 었 → 줬)" } },
    "l7-verb-maj-da": { note: "To be right or correct: 맞아요! is 'That's right!' The same verb also means 'to fit' and 'to be hit'.", example: { ko: "네, 맞아요.", en: "Yes, that's right.", form: "맞다 → 맞아요 (present, polite casual)" } },
    "l7-adjective-suip-da": { note: "To be easy. ㅂ irregular: 쉬워요. Its opposite is 어렵다.", example: { ko: "이 문제는 쉬워요.", en: "This problem is easy.", form: "쉽다 → 쉬워요 (ㅂ irregular: ㅂ → 우)" } },
    "l7-adjective-deop-da": { note: "To be hot, for weather or a place. Hot to the touch is 뜨겁다. ㅂ irregular: 더워요.", example: { ko: "여름에는 너무 더워요.", en: "It's very hot in summer.", form: "덥다 → 더워요 (ㅂ irregular)" } },
    "l7-adjective-geu-rip-da": { note: "To miss, to long for, especially a place, time or thing: 고향이 그리워요. ㅂ irregular: 그리워요.", example: { ko: "고향 음식이 그리워요.", en: "I miss the food from home.", form: "그립다 → 그리워요 (ㅂ irregular); the thing missed takes 이/가" } },
    "l7-adjective-gui-yeop-da": { note: "To be cute. ㅂ irregular: 귀여워요.", example: { ko: "아기가 정말 귀여워요.", en: "The baby is really cute.", form: "귀엽다 → 귀여워요 (ㅂ irregular)" } },
    "l7-adjective-chup-da": { note: "To be cold, for weather or how you feel. Cold to the touch is 차갑다. ㅂ irregular: 추워요.", example: { ko: "오늘 밖이 너무 추워요.", en: "It's very cold outside today.", form: "춥다 → 추워요 (ㅂ irregular)" } },
    "l7-adjective-eo-ryeop-da": { note: "To be difficult. ㅂ irregular: 어려워요. Its opposite is 쉽다.", example: { ko: "한국어 문법이 어려워요.", en: "Korean grammar is difficult.", form: "어렵다 → 어려워요 (ㅂ irregular)" } },
    "l7-adjective-deo-reop-da": { note: "To be dirty. ㅂ irregular: 더러워요. Its opposite is 깨끗하다.", example: { ko: "신발이 더러워요.", en: "My shoes are dirty.", form: "더럽다 → 더러워요 (ㅂ irregular)" } },
    "l7-adjective-ba-bbeu-da": { note: "To be busy. The ㅡ drops: 바빠요.", example: { ko: "요즘 너무 바빠요.", en: "I'm so busy these days.", form: "바쁘다 → 바빠요 (ㅡ drops before -아요)" } },
    "l7-adjective-gat-da": { note: "To be the same, with 와/과 or 하고 for 'same as'. 같이 means 'together'. After a noun, 같다 also means 'to seem like': 비가 올 것 같아요.", example: { ko: "제 생일은 친구 생일과 같아요.", en: "My birthday is the same as my friend's.", form: "생일 + 과 (as); 같다 → 같아요" } },
    "l7-adjective-an-jeon-ha-da": { note: "To be safe. Its opposite is 위험하다. The noun 안전 appears on signs: 안전 제일 (safety first).", example: { ko: "한국은 밤에도 안전해요.", en: "Korea is safe even at night.", form: "밤 + 에 + 도 (even at night); 안전하다 → 안전해요" } },
    "l7-adjective-ddak-ddak-ha-da": { note: "To be hard or stiff (bread, a chair). For a person or atmosphere, it means 'stiff/formal'. Hard as in difficult is 어렵다.", example: { ko: "이 빵은 너무 딱딱해요.", en: "This bread is too hard.", form: "딱딱하다 → 딱딱해요" } },
    "l7-adjective-bu-deu-reop-da": { note: "To be soft or smooth, for texture, voice or manner. ㅂ irregular: 부드러워요.", example: { ko: "이 이불은 아주 부드러워요.", en: "This blanket is very soft.", form: "부드럽다 → 부드러워요 (ㅂ irregular)" } },
    "l7-adjective-ga-neung-ha-da": { note: "To be possible. 가능해요? is a polite 'Can I / is it possible?' for requests in shops.", example: { ko: "카드 결제 가능해요?", en: "Can I pay by card?", form: "가능하다 → 가능해요? (rising tone for a question)" } },
    "l7-adjective-bul-ga-neung-ha-da": { note: "To be impossible: 불- (not) + 가능하다.", example: { ko: "하루에 다 하는 건 불가능해요.", en: "Doing it all in one day is impossible.", form: "하는 건 = 하는 것은 (doing, as a noun); 불가능하다 → 불가능해요" } },
    "l7-adverb-il-jjik": { note: "Early: 일찍 일어나다 (get up early). Its opposite is 늦게.", example: { ko: "내일 일찍 오세요.", en: "Please come early tomorrow.", form: "일찍 + 오세요 (adverb before the verb)" } },
    "l7-adverb-o-jeon": { note: "The morning hours, a.m.: 오전 10시. 아침 is morning as a time of day or breakfast.", example: { ko: "오전 9시에 수업이 있어요.", en: "I have class at 9 a.m.", form: "오전 9시 (아홉 시) + 에 (time)" } },
    "l7-adverb-o-hu": { note: "The afternoon, p.m.: 오후 3시. It covers noon until evening.", example: { ko: "오후에 만나요.", en: "Let's meet in the afternoon.", form: "오후 + 에 (time); 만나다 → 만나요" } },
    "l7-adverb-mae-il": { note: "Every day. 매 (every) also makes 매주 (every week) and 매년 (every year).", example: { ko: "매일 한국어를 공부해요.", en: "I study Korean every day.", form: "매일 (no 에 needed); 공부하다 → 공부해요" } },
    "l7-adverb-yeo-reum": { note: "Summer. Seasons take 에: 여름에. Summer vacation is 여름 방학 (school) or 여름 휴가 (work).", example: { ko: "여름에 바다에 가요.", en: "I go to the sea in summer.", form: "여름 + 에 (time); 바다 + 에 (destination)" } },
    "l7-adverb-ga-eul": { note: "Autumn or fall. 가을에 단풍이 예뻐요 — the fall leaves are pretty.", example: { ko: "가을은 날씨가 시원해요.", en: "The weather is cool in fall.", form: "가을 + 은 (topic); 시원하다 → 시원해요" } },
    "l7-adverb-gyeo-ul": { note: "Winter.", example: { ko: "겨울에 눈이 많이 와요.", en: "It snows a lot in winter.", form: "겨울 + 에 (time); 눈 + 이 오다 (snow falls)" } },
    "l7-adverb-bom": { note: "Spring. 봄에 꽃이 펴요 — flowers bloom in spring.", example: { ko: "봄이 오면 꽃이 펴요.", en: "When spring comes, flowers bloom.", form: "오다 → 오면 (when/if); 피다 → 펴요" } },
    "l7-noun-il": { note: "Work, or a task, a matter or an event. 무슨 일이에요? is 'What's the matter?' The same spelling is also the number one and 'day'.", example: { ko: "오늘 일이 많아요.", en: "I have a lot of work today.", form: "일 + 이 (subject); 많다 → 많아요" } },
    "l7-noun-nal-ssi": { note: "The weather. 날씨가 좋다 is 'the weather is nice'; 'How's the weather?' is 날씨가 어때요?", example: { ko: "날씨가 어때요?", en: "How's the weather?", form: "날씨 + 가 (subject); 어떻다 → 어때요" } },
    "l7-verb-is-da": { note: "To connect or continue. ㅅ irregular: 이어요, 이었어요. Not to be confused with 있다.", example: { ko: "두 줄을 이어 주세요.", en: "Please connect the two lines.", form: "잇다 → 이어 + 주세요 (ㅅ drops before a vowel)" } },
    "l7-verb-us-da": { note: "To laugh or smile. It's regular: 웃어요. 'Laugh at someone' is 비웃다.", example: { ko: "아기가 웃어요.", en: "The baby is smiling.", form: "웃다 → 웃어요 (regular, ㅅ stays)" } },
    "l7-verb-beos-da": { note: "To take off clothes, shoes or glasses. It's regular: 벗어요. The opposite depends on the item: 입다, 신다, 쓰다.", example: { ko: "코트를 벗으세요.", en: "Please take off your coat.", form: "벗다 → 벗으세요 (polite request; regular)" } },
    "l7-verb-ssis-da": { note: "To wash your body, hands or food. Dishes are 설거지하다; clothes are 빨다 or 빨래하다. It's regular: 씻어요.", example: { ko: "손을 씻으세요.", en: "Please wash your hands.", form: "씻다 → 씻으세요 (regular, ㅅ stays)" } },
    "l7-verb-geot-da": { note: "To roll up or tuck up (sleeves, trouser legs). It's regular: 걷어요, unlike 걷다 'to walk' (걸어요).", example: { ko: "소매를 걷었어요.", en: "I rolled up my sleeves.", form: "걷다 → 걷었어요 (regular, ㄷ stays)" } },
    "l7-verb-geol-da": { note: "To hang something (벽에 걸다), and also 'make a phone call' (전화를 걸다). ㄹ stem: 거세요, 겁니다.", example: { ko: "벽에 그림을 걸었어요.", en: "I hung a picture on the wall.", form: "벽 + 에 (location); 걸다 → 걸었어요" } },
    "l7-verb-bat-da": { note: "To receive or get: 선물을 받다; also 'answer' the phone (전화를 받다). It's regular: 받아요.", example: { ko: "전화를 받으세요.", en: "Please answer the phone.", form: "받다 → 받으세요 (regular, ㄷ stays)" } },
    "l7-verb-mut-da": { note: "To bury (regular: 묻어요). The same spelling also means 'to ask', which is ㄷ irregular: 물어요.", example: { ko: "개가 뼈를 땅에 묻었어요.", en: "The dog buried a bone in the ground.", form: "묻다 (bury) → 묻었어요 (regular)" } },
    "l7-verb-jup-da": { note: "To pick up something from the ground. ㅂ irregular: 주워요.", example: { ko: "길에서 돈을 주웠어요.", en: "I picked up money on the street.", form: "줍다 → 주웠어요 (ㅂ irregular)" } },
    "l7-verb-nup-da": { note: "To lie down. ㅂ irregular: 누워요. 'Lie in bed' is 침대에 눕다.", example: { ko: "피곤해서 침대에 누웠어요.", en: "I was tired, so I lay down on the bed.", form: "눕다 → 누웠어요 (ㅂ irregular)" } },
    "l7-verb-jap-da": { note: "To catch or grab. Also 'hail a taxi' (택시를 잡다) and 'hold hands' (손을 잡다). It's regular: 잡아요.", example: { ko: "손을 잡아 주세요.", en: "Please hold my hand.", form: "잡다 → 잡아 + 주세요 (regular, ㅂ stays)" } },
    "l7-verb-geulk-da": { note: "To scratch. The ㄹㄱ batchim is said 극 at the end: 극따, but 글거요 before a vowel.", example: { ko: "고양이가 소파를 긁었어요.", en: "The cat scratched the sofa.", form: "긁다 → 긁었어요 (both batchim letters sound before a vowel)" } },
    "l7-verb-dda-reu-da": { note: "To follow, and also to pour a drink. ㅡ irregular (not 르): 따라요.", example: { ko: "저를 따라오세요.", en: "Please follow me.", form: "따르다 → 따라 + 오세요 (come following)" } },
    "l7-verb-bu-reu-da": { note: "To call someone (이름을 부르다), sing a song (노래를 부르다), or be full (배가 부르다). 르 irregular: 불러요.", example: { ko: "같이 노래를 불러요.", en: "Let's sing a song together.", form: "부르다 → 불러요 (르 irregular)" } },
    "l7-verb-go-reu-da": { note: "To choose or pick. 르 irregular: 골라요. 골라 주세요 is 'please pick for me'.", example: { ko: "하나만 고르세요.", en: "Choose just one.", form: "고르다 → 고르세요 (polite request)" } },
    "l7-verb-deul-da": { note: "To lift or hold (가방을 들다), and also to enter or to cost money (돈이 들다). ㄹ stem: its 드세요 ('please hold') looks just like 드세요 from 드시다, the honorific of 먹다.", example: { ko: "가방을 들어 드릴게요.", en: "Let me carry your bag for you.", form: "들다 → 들어 + 드릴게요 (I'll do it for you, humble)" } },
    "l7-verb-gal-da": { note: "To change or replace (배터리를 갈다) and to grind (커피를 갈다). ㄹ stem: 갑니다 here looks like 가다!", example: { ko: "전구를 갈았어요.", en: "I changed the light bulb.", form: "갈다 → 갈았어요 (past)" } },
    "l7-verb-bbal-da": { note: "To wash clothes (옷을 빨다), and also to suck (a straw). Laundry as a chore is 빨래하다.", example: { ko: "주말에 옷을 빨아요.", en: "I wash clothes on the weekend.", form: "빨다 → 빨아요 (ㄹ stem, regular before -아요)" } },
    "l7-adjective-nas-da": { note: "To be better (than something). ㅅ irregular: 나아요. As a verb it also means 'to get better / recover': 감기가 나았어요. Not 낳다 (give birth).", example: { ko: "이게 그것보다 나아요.", en: "This is better than that.", form: "그것 + 보다 (than); 낫다 → 나아요 (ㅅ drops)" } },
    "l7-adjective-gop-da": { note: "To be beautiful or fine, often for hands, skin, colors or a kind heart. ㅂ irregular, but with 오: 고와요.", example: { ko: "할머니 손이 참 고와요.", en: "Grandma's hands are really lovely.", form: "곱다 → 고와요 (ㅂ → 오, like 돕다)" } },
    "l7-adjective-jop-da": { note: "To be narrow or cramped. It's regular: 좁아요. Its opposite is 넓다.", example: { ko: "이 길은 너무 좁아요.", en: "This road is too narrow.", form: "좁다 → 좁아요 (regular, ㅂ stays)" } },
    "l7-adjective-neolp-da": { note: "To be wide or spacious. The ㄹㅂ batchim is said 널 at the end (널따), but 널버요 before a vowel.", example: { ko: "제 방은 넓어요.", en: "My room is spacious.", form: "넓다 → 넓어요 (regular)" } },
    "l7-adjective-ye-bbeu-da": { note: "To be pretty, the everyday word for people and things. ㅡ drops: 예뻐요.", example: { ko: "이 꽃 정말 예뻐요.", en: "This flower is really pretty.", form: "예쁘다 → 예뻐요 (ㅡ drops before -어요)" } },
    "l7-adjective-eops-da": { note: "To not exist or not have, the opposite of 있다. The ㅂㅅ batchim is said 업 at the end (업따), 업서요 before a vowel.", example: { ko: "오늘은 시간이 없어요.", en: "I don't have time today.", form: "시간 + 이 (subject); 없다 → 없어요" } }
  };

  return { NOTES };
});
